const DEVELOPER_GUIDE = '/docs';
type Customer = { id:string; externalCustomerId:string; name:string; email?:string; monthlyRevenue:number; currency:string; revenueSource:string; stripeCustomerId?:string; revenueStale:boolean; revenueUpdatedAt?:string; stripeCustomerStatus:string };
type Row = { customerId:string; name:string; stripeCustomerStatus:string; revenue:number; aiCost:number; grossProfit:number; grossMargin:number|null; status:string;allowedAiBudget:number;remainingAiBudget:number;budgetUsedPercent:number|null;budgetState:string };
type Subscription = {id:string;externalSubscriptionId:string;name:string;status:string;currency:string;monthlyRecurringRevenue:number;currentPeriodStart?:string;currentPeriodEnd?:string;cancelAtPeriodEnd:boolean;warning?:string};
type Margin = Row & { targetGrossMargin:number; warningThreshold:number;criticalThreshold:number;targetGrossMarginOverride:number|null;warningThresholdOverride:number|null;criticalThresholdOverride:number|null;features:{feature:string;cost:number}[]; recentUsage:{id:string;provider:string;model:string;feature:string;inputTokens:number;outputTokens:number;cost:number;occurredAt:string}[]; revenueSource:string;stripeCustomerId?:string;revenueStale:boolean;revenueUpdatedAt?:string;subscriptions?:Subscription[];stripeCustomerStatus:string };
type StripeConnection = {connected:boolean;accountId?:string;liveMode:boolean;status:string;lastSyncAt?:string;lastSuccessfulSyncAt?:string;lastError?:string;webhookConfigured:boolean;webhookPath?:string};
type UsageApiKey = {id:string;name:string;keyPrefix:string;status:string;createdAt:string;revokedAt?:string;lastUsedAt?:string;secret?:string};
type OnboardingState = {onboardingStatus:'not_started'|'in_progress'|'completed';requiresOnboarding:boolean;stripeConnected:boolean;ingestionKeyCreated:boolean;firstUsageReceived:boolean;customerCount:number;usageEventCount:number;startedAt:string|null;completedAt:string|null};
type CustomerPage = {items:Row[];total:number;page:number;pageSize:number};
type Analytics = {period:{range:string;start:string;endExclusive:string;revenueSemantics:'period_end_mrr'};sort:string;totals:{revenue:number;aiCost:number;grossProfit:number;grossMargin:number|null};trend:{date:string;cost:number}[];breakdowns:{providers:{name:string;cost:number;requests:number}[];models:{name:string;cost:number;requests:number}[];features:{name:string;cost:number;requests:number}[];customers:{name:string;cost:number}[]};customers:Row[]|CustomerPage;currentHealth:{critical:number;warning:number;highestRisk:Row|null};insights:{tone:'critical'|'healthy'|'neutral';text:string;customerId?:string}[];anomalies:{dimension:'customer'|'feature'|'model';name:string;customerId?:string;currentCost:number;previousCost:number;absoluteIncrease:number;percentageIncrease:number|null;severity:'warning'|'critical'}[];topCostDrivers:{customers:{name:string;cost:number}[];features:{name:string;cost:number}[];models:{name:string;cost:number}[]}};
type CustomerPeriodProfitability = Row & {period:Analytics['period'];targetGrossMargin:number;warningThreshold:number;criticalThreshold:number;features:{feature:string;cost:number}[];recentUsage:Margin['recentUsage']};
type ProfitabilityHistoryMonth = {periodStart:string;periodEnd:string;revenue:number;aiCost:number;grossProfit:number;grossMargin:number|null;status:string;usageEventCount:number};
type CustomerForecast = {forecastStatus:'available'|'insufficient_data';asOf:string;revenue:number;currentMonthAiCost:number;recentWindowDays:number;recentDailyAverageCost:number;projectedMonthEndAiCost:number|null;allowedAiBudget:number;remainingBudget:number;projectedRemainingBudget:number|null;projectedGrossProfit:number|null;projectedGrossMargin:number|null;budgetExhausted:boolean;budgetExhaustionDate:string|null};
type OrganizationForecastSummary = {forecastStatus:'available'|'insufficient_data';asOf:string;scope:'current_month';currentRevenue:number;currentMonthAiCost:number;recentWindowDays:number;recentDailyAverageCost:number;projectedMonthEndAiCost:number|null;projectedGrossProfit:number|null;projectedGrossMargin:number|null;customersEvaluated:number;customersInsufficientData:number;customersAlreadyBudgetExhausted:number;customersProjectedToExhaustBudgetThisMonth:number;highestForecastRisk:{customerId:string;customerName:string;projectedMonthEndAiCost:number|null;allowedAiBudget:number;budgetExhaustionDate:string|null}|null};
type CustomerCostDriver = {name:string;aiCost:number;shareOfCustomerAiCost:number;previousPeriodAiCost:number;absoluteChange:number;percentChange:number|null;direction:'up'|'down'|'flat';usageEventCount:number};
type CustomerCostDriversResponse = {range:{value:string;start:string;endExclusive:string;previousStart:string;previousEndExclusive:string};totalAiCost:number;features:CustomerCostDriver[];models:CustomerCostDriver[]};

type SelectOption<T extends string>={value:T;label:string;tone?:'healthy'|'warning'|'critical'|'deleted'};
function CustomSelect<T extends string>({value,options,onChange,ariaLabel,className=''}:{value:T;options:readonly SelectOption<T>[];onChange:(value:T)=>void;ariaLabel:string;className?:string}){
  const id=useId();const trigger=useRef<HTMLButtonElement>(null);const panel=useRef<HTMLDivElement>(null);const [open,setOpen]=useState(false);const [active,setActive]=useState(Math.max(0,options.findIndex(option=>option.value===value)));const [position,setPosition]=useState({top:0,left:0,width:0,maxHeight:280});
  const selected=options.find(option=>option.value===value)??options[0];
  const place=useCallback(()=>{const rect=trigger.current?.getBoundingClientRect();if(!rect)return;const below=window.innerHeight-rect.bottom-12;const above=rect.top-12;const opensAbove=below<160&&above>below;const maxHeight=Math.min(280,Math.max(100,opensAbove?above:below));setPosition({top:opensAbove?Math.max(8,rect.top-6-maxHeight):rect.bottom+6,left:Math.min(rect.left,Math.max(12,window.innerWidth-rect.width-12)),width:rect.width,maxHeight});},[]);
  const show=()=>{setActive(Math.max(0,options.findIndex(option=>option.value===value)));place();setOpen(true);};
  const choose=(option:SelectOption<T>)=>{onChange(option.value);setOpen(false);trigger.current?.focus();};
  useEffect(()=>{if(!open)return;const outside=(event:PointerEvent)=>{const target=event.target as Node;if(!trigger.current?.contains(target)&&!panel.current?.contains(target))setOpen(false);};const reposition=()=>place();document.addEventListener('pointerdown',outside);window.addEventListener('resize',reposition);window.addEventListener('scroll',reposition,true);return()=>{document.removeEventListener('pointerdown',outside);window.removeEventListener('resize',reposition);window.removeEventListener('scroll',reposition,true);};},[open,place]);
  const keyDown=(event:React.KeyboardEvent<HTMLButtonElement>)=>{if(event.key==='Escape'){if(open){event.preventDefault();setOpen(false);}return;}if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(!open){show();return;}setActive(index=>(index+(event.key==='ArrowDown'?1:-1)+options.length)%options.length);return;}if(event.key==='Home'||event.key==='End'){if(!open)return;event.preventDefault();setActive(event.key==='Home'?0:options.length-1);return;}if((event.key==='Enter'||event.key===' ')&&open){event.preventDefault();const option=options[active];if(option)choose(option);return;}if((event.key==='Enter'||event.key===' ')&&!open){event.preventDefault();show();}};
  return <span className={`custom-select ${className}`}><button ref={trigger} type="button" className="custom-select-trigger" aria-label={ariaLabel} role="combobox" aria-haspopup="listbox" aria-expanded={open} aria-controls={`${id}-listbox`} aria-activedescendant={open?`${id}-option-${active}`:undefined} onClick={()=>open?setOpen(false):show()} onKeyDown={keyDown}><span>{selected?.tone&&<i className={`select-status-dot ${selected.tone}`} aria-hidden="true"/>}{selected?.label}</span><i className="select-chevron" aria-hidden="true"/></button>{open&&createPortal(<div ref={panel} id={`${id}-listbox`} className="custom-select-menu" role="listbox" aria-label={ariaLabel} style={{top:position.top,left:position.left,width:position.width,maxHeight:position.maxHeight}}>{options.map((option,index)=><button id={`${id}-option-${index}`} key={option.value} type="button" role="option" aria-selected={option.value===value} className={`${index===active?'active':''} ${option.value===value?'selected':''}`} onMouseEnter={()=>setActive(index)} onClick={()=>choose(option)}><span>{option.tone&&<i className={`select-status-dot ${option.tone}`} aria-hidden="true"/>}{option.label}</span>{option.value===value&&<span className="select-check" aria-hidden="true">✓</span>}</button>)}</div>,document.body)}</span>;
}
function Status({value}:{value:string}) { return <span className={`status ${value}`}>{value==='atRisk'?'At Risk':value==='noRevenue'?'No Revenue':value[0].toUpperCase()+value.slice(1)}</span>; }
function BudgetIndicator({value}:{value:string}){return <span className={`budget-indicator ${value}`}>{value[0].toUpperCase()+value.slice(1)}</span>}
const customerRiskState=(customer:Row)=>customer.stripeCustomerStatus==='deleted'?'deleted':customer.budgetState;

function Auth({register=false}:{register?:boolean}) {
  const nav=useNavigate(); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  async function submit(e:FormEvent<HTMLFormElement>) {
    e.preventDefault(); if (busy) return; setBusy(true); setError(''); const fd=new FormData(e.currentTarget);
    try {
      const data=await request<{accessToken:string}>(`/api/v1/auth/${register?'register':'login'}`,{method:'POST',body:JSON.stringify(register?{email:fd.get('email'),password:fd.get('password'),organizationName:fd.get('organization')}:{email:fd.get('email'),password:fd.get('password')})});
      localStorage.setItem('token',data.accessToken);
      const onboarding=await request<OnboardingState>('/api/v1/onboarding');
      void nav(onboarding.requiresOnboarding?'/onboarding':'/dashboard');
    } catch(x) { localStorage.removeItem('token'); setError((x as Error).message); } finally { setBusy(false); }
  }
  return <main className="auth"><section className="auth-brand"><div className="logo">M</div><h1>Know the margin behind every customer.</h1><p>Revenue tells half the story. Margintra connects monthly revenue to AI usage costs so you can see who is profitable—and who needs attention.</p></section><section className="auth-card"><div><span className="eyebrow">Margintra</span><h2>{register?'Create your workspace':'Welcome back'}</h2><p>{register?'Start measuring customer profitability.':'Sign in to your margin dashboard.'}</p></div><form onSubmit={submit}>{register&&<label>Organization<input name="organization" required maxLength={200} placeholder="Margin Labs" /></label>}<label>Work email<input name="email" type="email" required maxLength={320} placeholder="you@company.com" /></label><label>Password<input name="password" type="password" minLength={8} maxLength={128} required placeholder="At least 8 characters" /></label>{error&&<div className="error">{error}</div>}<button disabled={busy}>{busy?'Please wait…':register?'Create workspace':'Sign in'}</button></form><p className="switch">{register?'Already have an account? ':'New to Margintra? '}<Link to={register?'/login':'/register'}>{register?'Sign in':'Create an account'}</Link></p>{!register&&<p className="demo">Demo: demo@margintra.local / Demo123!</p>}</section></main>;
}

function NavIcon({name}:{name:'overview'|'customers'|'integrations'|'settings'}){const paths={overview:<><path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/></>,customers:<><path d="M16 20v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 20v-2a4 4 0 0 0-3-3.87M16 2.13a4 4 0 0 1 0 7.75"/></>,integrations:<><path d="M9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0M12 2v3M12 19v3M4.93 4.93l2.12 2.12M16.95 16.95l2.12 2.12M2 12h3M19 12h3M4.93 19.07l2.12-2.12M16.95 7.05l2.12-2.12"/></>,settings:<><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-2.83 2.83-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21h-4v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06-2.83-2.83.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3v-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06 2.83-2.83.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3h4v.09A1.65 1.65 0 0 0 15 4.6a1.65 1.65 0 0 0 1.82-.33l.06-.06 2.83 2.83-.06.06A1.65 1.65 0 0 0 19.32 9a1.65 1.65 0 0 0 1.51 1H21v4h-.09A1.65 1.65 0 0 0 19.4 15z"/></>};return <svg className="nav-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{paths[name]}</svg>}
function Shell(){const nav=useNavigate();const item=({isActive}:{isActive:boolean})=>isActive?'active':undefined;return <div className="shell"><aside><Link className="brand" to="/dashboard"><span>M</span><span className="brand-name">Margintra<small>Financial intelligence</small></span></Link><div className="nav-label">Workspace</div><nav><NavLink className={item} to="/dashboard"><NavIcon name="overview"/><span>Overview</span></NavLink><NavLink className={item} to="/customers"><NavIcon name="customers"/><span>Customers</span></NavLink><NavLink className={item} to="/integrations"><NavIcon name="integrations"/><span>Integrations</span></NavLink><NavLink className={item} to="/settings"><NavIcon name="settings"/><span>Settings</span></NavLink></nav><div className="aside-foot"><a className="developer-docs-link" href={DEVELOPER_GUIDE} target="_blank" rel="noopener noreferrer">Developer docs <span aria-hidden="true">↗</span></a><div className="workspace-mark"><span>MT</span><div><strong>Margintra</strong><small>Workspace</small></div></div><button className="ghost" onClick={()=>{localStorage.removeItem('token');void nav('/login')}}>Sign out</button></div></aside><main className="content"><div className="content-inner"><Outlet/></div></main></div>}
function Guard(){return localStorage.getItem('token')?<OnboardingGate/>:<Navigate to="/login"/>}
function OnboardingGate(){
  const location=useLocation(); const [state,setState]=useState<{path:string;data?:OnboardingState;error?:string}>({path:''});
  useEffect(()=>{let active=true;request<OnboardingState>('/api/v1/onboarding').then(data=>{if(active)setState({path:location.pathname,data});}).catch(error=>{if(active)setState({path:location.pathname,error:(error as Error).message});});return()=>{active=false;};},[location.pathname]);
  if(state.path!==location.pathname)return <p>Checking workspace setup…</p>;
  if(state.error)return <div className="error">{state.error}</div>;
  if(!state.data)return <p>Checking workspace setup…</p>;
  if(state.data.requiresOnboarding&&location.pathname!=='/onboarding')return <Navigate to="/onboarding" replace/>;
  if(state.data.requiresOnboarding)return <Outlet/>;
  return <Shell/>;
}

function PageHead({title,subtitle,action,eyebrow='Current calendar month'}:{title:string;subtitle:string;action?:React.ReactNode;eyebrow?:string}){return <header className="page-head"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{subtitle}</p></div>{action}</header>}
function Term({children,definition}:{children:React.ReactNode;definition:string}){
  const id=useId(); const trigger=useRef<HTMLButtonElement>(null); const timer=useRef<number|undefined>(undefined); const [tooltip,setTooltip]=useState<{top:number;left:number}|null>(null);
  const close=()=>{window.clearTimeout(timer.current);setTooltip(null);};
  const open=()=>{const rect=trigger.current?.getBoundingClientRect();if(!rect)return;const width=Math.min(340,window.innerWidth-24);setTooltip({top:rect.bottom+7,left:Math.max(12,Math.min(rect.left+rect.width/2-width/2,window.innerWidth-width-12))});};
  const delayedOpen=()=>{window.clearTimeout(timer.current);timer.current=window.setTimeout(open,120);};
  useEffect(()=>()=>window.clearTimeout(timer.current),[]);
  return <span className="term-wrap"><button ref={trigger} type="button" className="term" aria-describedby={tooltip?id:undefined} onMouseEnter={delayedOpen} onMouseLeave={close} onFocus={open} onBlur={close}>{children}<span aria-hidden="true">?</span></button>{tooltip&&createPortal(<span id={id} role="tooltip" className="custom-tooltip" style={{top:tooltip.top,left:tooltip.left}}>{definition}</span>,document.body)}</span>;
}
function AnalyticsMetric({label,value,tone='default',helper}:{label:string;value:string;tone?:'default'|'cost'|'profit'|'margin'|'risk';helper?:React.ReactNode}){return <article className={`metric analytics-kpi ${tone}`}><div className="kpi-top"><span className="kpi-label">{label}</span></div><strong>{value}</strong>{helper&&<small>{helper}</small>}</article>}
function CustomerTable({rows,periodQuery}:{rows:Row[];periodQuery:string}){return <div className="table-wrap profitability-table"><table><thead><tr><th>Customer</th><th className="number-col">Revenue</th><th className="number-col">AI cost</th><th className="number-col">Gross profit</th><th className="number-col">Margin</th><th><Term definition="The maximum AI cost that preserves the configured target gross margin.">AI budget</Term></th><th>Period status</th></tr></thead><tbody>{rows.map(r=>{const used=r.budgetUsedPercent;const meter=used===null?0:Math.max(0,Math.min(100,used));const riskState=customerRiskState(r);return <tr key={r.customerId} className={`risk-${riskState}`}><td className="customer-cell"><Link to={`/customers/${r.customerId}?${periodQuery}`}>{r.name}</Link>{r.revenue===0&&<small>No recognized revenue</small>}</td><td className="number-col revenue-cell">{money(r.revenue)}</td><td className="number-col cost-cell">{money(r.aiCost)}</td><td className={`number-col profit-cell ${r.grossProfit<0?'negative':''}`}>{money(r.grossProfit)}</td><td className={`number-col margin-cell ${r.grossMargin===null?'na-value':r.grossMargin<0?'negative':''}`}>{pct(r.grossMargin)}</td><td className={`budget-summary-cell ${used===null?'na-value':''}`}><div><Term definition="AI cost divided by the allowed AI budget. Values above 100% mean the budget is exceeded."><strong>{used===null?'N/A':`${used.toFixed(0)}% used`}</strong></Term><span className={r.remainingAiBudget<0?'negative':''}>{r.remainingAiBudget<0?`${money(Math.abs(r.remainingAiBudget))} over budget`:`${money(r.remainingAiBudget)} remaining`}</span><small>Allowed {money(r.allowedAiBudget)}</small></div>{used!==null&&<span className="budget-meter"><i style={{width:`${meter}%`}}/></span>}</td><td><BudgetIndicator value={riskState}/></td></tr>})}{rows.length===0&&<tr><td colSpan={7} className="empty">No customers yet. Add one to begin measuring margin.</td></tr>}</tbody></table></div>}

function MonthEndForecast({customerId}:{customerId:string}){
  const forecast=useLoad<CustomerForecast>(`/api/v1/analytics/profitability/customers/${customerId}/forecast`);
  if(forecast.loading)return <section className="panel month-end-forecast"><div className="forecast-head"><div><h2>Month-end forecast</h2><p>Estimated from recent AI spend velocity.</p></div><span>Estimate</span></div><p className="forecast-loading">Loading month-end forecast…</p></section>;
  if(forecast.error)return <section className="panel month-end-forecast"><div className="forecast-head"><div><h2>Month-end forecast</h2><p>Estimated from recent AI spend velocity.</p></div><span>Estimate</span></div><div className="error forecast-error">{forecast.error}</div></section>;
  const data=forecast.data;
  if(!data)return null;
  if(data.forecastStatus==='insufficient_data')return <section className="panel month-end-forecast"><div className="forecast-head"><div><h2>Month-end forecast</h2><p>Estimated from recent AI spend velocity.</p></div><span>Estimate</span></div><div className="forecast-insufficient"><strong>Not enough usage history to forecast this month yet.</strong><span>Margintra needs at least 3 days of usage history.</span><small>Recent daily AI spend: {money(data.recentDailyAverageCost)}/day · based on {data.recentWindowDays} {data.recentWindowDays===1?'day':'days'}</small></div></section>;
  const projectedCost=data.projectedMonthEndAiCost!;const scale=Math.max(1,data.currentMonthAiCost,projectedCost,data.allowedAiBudget);
  const barWidth=(value:number)=>`${Math.max(0,value)/scale*100}%`;
  const insight=data.budgetExhausted
    ?{tone:'critical',text:'AI budget is already exhausted for this month.'}
    :data.budgetExhaustionDate
      ?{tone:'warning',text:`AI budget may be exhausted by ${new Date(data.budgetExhaustionDate).toLocaleDateString(undefined,{month:'short',day:'numeric',timeZone:'UTC'})}.`}
      :{tone:'healthy',text:'AI budget is not projected to be exhausted this month.'};
  return <section className="panel month-end-forecast"><div className="forecast-head"><div><h2>Month-end forecast</h2><p>Estimated from recent AI spend velocity.</p></div><span>Estimate</span></div>
    <div className="forecast-metrics"><div><span>Projected AI cost</span><strong>{money(projectedCost)}</strong><small>Estimated month end</small></div><div><span>Projected gross margin</span><strong>{pct(data.projectedGrossMargin)}</strong><small>Estimated month end</small></div><div><span>Projected gross profit</span><strong className={data.projectedGrossProfit!==null&&data.projectedGrossProfit<0?'negative':''}>{data.projectedGrossProfit===null?'—':money(data.projectedGrossProfit)}</strong><small>Estimated month end</small></div><div><span>Projected remaining budget</span><strong className={data.projectedRemainingBudget!==null&&data.projectedRemainingBudget<0?'negative':''}>{data.projectedRemainingBudget===null?'—':money(data.projectedRemainingBudget)}</strong><small>Estimated month end</small></div></div>
    <div className={`forecast-insight ${insight.tone}`}><span aria-hidden="true"/><strong>{insight.text}</strong></div>
    <div className="forecast-comparison" aria-label="Current and projected AI cost compared with allowed AI budget"><div className="forecast-bar-row"><div><span>Current AI cost</span><strong>{money(data.currentMonthAiCost)}</strong></div><i><span className="actual" style={{width:barWidth(data.currentMonthAiCost)}}/></i></div><div className="forecast-bar-row"><div><span>Projected month-end AI cost</span><strong>{money(projectedCost)}</strong></div><i><span className="projected" style={{width:barWidth(projectedCost)}}/></i></div><div className="forecast-bar-row"><div><span>Allowed AI budget</span><strong>{money(data.allowedAiBudget)}</strong></div><i><span className="budget" style={{width:barWidth(data.allowedAiBudget)}}/></i></div></div>
    <p className="forecast-velocity">Recent daily AI spend: <strong>{money(data.recentDailyAverageCost)}/day</strong> · based on {data.recentWindowDays} {data.recentWindowDays===1?'day':'days'} <span>Forecast only—not actual incurred spend.</span></p>
  </section>;
}

const historyRangeOptions=[{value:'6',label:'6 months'},{value:'12',label:'12 months'},{value:'24',label:'24 months'},{value:'custom',label:'Custom range'}] as const;
const historyMonthLabel=(value:string,short=false)=>new Date(value).toLocaleDateString(undefined,{month:short?'short':'long',year:short?undefined:'numeric',timeZone:'UTC'});
const monthInputValue=(date:Date)=>date.toISOString().slice(0,7);
const monthBoundary=(month:string,offset=0)=>{const [year,value]=month.split('-').map(Number);return new Date(Date.UTC(year!,value!-1+offset,1)).toISOString();};
function linePath(points:{x:number;y:number}[]){return points.map((point,index)=>`${index?'L':'M'} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(' ')}
function ProfitabilityHistory({customerId}:{customerId:string}){
  const now=new Date();const currentMonth=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),1));
  const [range,setRange]=useState<'6'|'12'|'24'|'custom'>('12');
  const months=range;
  const [fromMonth,setFromMonth]=useState(monthInputValue(new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-11,1))));
  const [toMonth,setToMonth]=useState(monthInputValue(currentMonth));
  const customValid=Boolean(fromMonth&&toMonth&&fromMonth<=toMonth);
  const historyQuery=range==='custom'&&customValid?`start=${encodeURIComponent(monthBoundary(fromMonth))}&end=${encodeURIComponent(monthBoundary(toMonth,1))}`:`months=${range==='custom'?'12':range}`;
  const history=useLoad<ProfitabilityHistoryMonth[]>(`/api/v1/analytics/profitability/customers/${customerId}/history?${historyQuery}`);
  const [revenueActive,setRevenueActive]=useState<number|null>(null);
  const [costActive,setCostActive]=useState<number|null>(null);
  const [marginActive,setMarginActive]=useState<number|null>(null);
  const controls=<div className="history-range-controls"><CustomSelect value={range} options={historyRangeOptions} onChange={setRange} ariaLabel="Profitability history range"/>{range==='custom'&&<><label>From<input type="month" value={fromMonth} onInput={event=>setFromMonth(event.currentTarget.value)}/></label><label>To<input type="month" value={toMonth} min={fromMonth} onInput={event=>setToMonth(event.currentTarget.value)}/></label></>}</div>;
  const head=<div className="history-head"><div><h2>Profitability history</h2><p>Monthly period-end revenue and processed AI cost.</p></div>{controls}</div>;
  if(!customValid)return <section className="panel profitability-history">{head}<div className="error history-error">From month must not be after To month.</div></section>;
  if(history.loading)return <section className="panel profitability-history">{head}<p className="history-loading">Loading profitability history…</p></section>;
  if(history.error)return <section className="panel profitability-history">{head}<div className="error history-error">{history.error}</div></section>;
  const rows=[...(history.data??[])].sort((a,b)=>a.periodStart.localeCompare(b.periodStart));
  const usable=rows.some(row=>row.revenue!==0||row.aiCost!==0||row.usageEventCount>0);
  if(!usable)return <section className="panel profitability-history">{head}<p className="empty history-empty">No profitability history yet.</p></section>;
  const width=900;const height=210;const left=68;const right=18;const top=16;const bottom=28;const plotWidth=width-left-right;const plotHeight=height-top-bottom;
  const maxRevenue=Math.max(1,...rows.map(row=>row.revenue));
  const maxCost=Math.max(0,...rows.map(row=>row.aiCost));
  const x=(index:number)=>left+(rows.length===1?plotWidth/2:(index/(rows.length-1))*plotWidth);
  const revenueY=(value:number)=>top+plotHeight-(value/maxRevenue)*plotHeight;
  const costHeight=92;const costTop=10;const costBottom=18;const costPlotHeight=costHeight-costTop-costBottom;
  const costY=(value:number)=>costTop+costPlotHeight-(maxCost===0?0:(value/maxCost)*costPlotHeight);
  const columnWidth=Math.max(8,Math.min(34,plotWidth/Math.max(rows.length,1)*.58));
  const marginValues=rows.flatMap(row=>row.grossMargin===null?[]:[row.grossMargin]);
  const marginMin=Math.min(0,...marginValues);const marginMax=Math.max(100,...marginValues);const marginSpan=Math.max(1,marginMax-marginMin);
  const marginTop=12;const marginPlotHeight=82;
  const marginY=(value:number)=>marginTop+marginPlotHeight-((value-marginMin)/marginSpan)*marginPlotHeight;
  const marginSegments: {x:number;y:number}[][]=[];let segment:{x:number;y:number}[]=[];
  rows.forEach((row,index)=>{if(row.grossMargin===null){if(segment.length)marginSegments.push(segment);segment=[];}else segment.push({x:x(index),y:marginY(row.grossMargin)});});if(segment.length)marginSegments.push(segment);
  const revenueSelected=revenueActive===null?null:rows[revenueActive];
  const costSelected=costActive===null?null:rows[costActive];
  const marginSelected=marginActive===null?null:rows[marginActive];
  const labelEvery=rows.length>12?2:1;
  const chartOverflowClass='';
  const chartSizing=undefined;
  const monthAxis=()=> <div className="history-x-labels" style={{paddingLeft:`${left/width*100}%`,paddingRight:`${right/width*100}%`,gridTemplateColumns:`repeat(${rows.length},1fr)`}}>{rows.map((row,index)=><span key={row.periodStart}>{index%labelEvery===0||index===rows.length-1?historyMonthLabel(row.periodStart,true):''}</span>)}</div>;
  return <section className={`panel profitability-history${rows.length>18?' history-labels-dense':''}`}>{head}
    <div className="history-legend" aria-hidden="true"><span className="revenue">Period-end MRR</span></div>
    <div className="history-chart-scroll"><div className="history-chart" onMouseLeave={()=>setRevenueActive(null)}>
      <svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Monthly period-end MRR shown as discrete columns"><g className="history-grid"><line x1={left} y1={top} x2={width-right} y2={top}/><line x1={left} y1={top+plotHeight/2} x2={width-right} y2={top+plotHeight/2}/><line x1={left} y1={top+plotHeight} x2={width-right} y2={top+plotHeight}/></g><g className="history-y-labels"><text x={left-10} y={top+4}>{money(maxRevenue)}</text><text x={left-10} y={top+plotHeight/2+4}>{money(maxRevenue/2)}</text><text x={left-10} y={top+plotHeight+4}>{money(0)}</text></g>{rows.map((row,index)=><rect className="history-revenue-column" key={row.periodStart} x={x(index)-columnWidth/2} y={revenueY(row.revenue)} width={columnWidth} height={Math.max(1,top+plotHeight-revenueY(row.revenue))} rx="3"/>)}</svg>
      <div className="history-hit-grid" style={{left:`${left/width*100}%`,right:`${right/width*100}%`}}>{rows.map((row,index)=><button key={row.periodStart} type="button" aria-label={`${historyMonthLabel(row.periodStart)}: Revenue ${money(row.revenue)}, AI cost ${money(row.aiCost)}`} onMouseEnter={()=>setRevenueActive(index)} onFocus={()=>setRevenueActive(index)} onBlur={()=>setRevenueActive(null)}/>)}</div>
      {revenueSelected&&<div className="history-tooltip" role="tooltip" style={{left:`${Math.max(12,Math.min(88,x(revenueActive!)/width*100))}%`}}><strong>{historyMonthLabel(revenueSelected.periodStart)}</strong><dl><div><dt>Revenue</dt><dd>{money(revenueSelected.revenue)}</dd></div><div><dt>AI cost</dt><dd>{money(revenueSelected.aiCost)}</dd></div><div><dt>Gross profit</dt><dd>{money(revenueSelected.grossProfit)}</dd></div><div><dt>Gross margin</dt><dd>{pct(revenueSelected.grossMargin)}</dd></div></dl><Status value={revenueSelected.status}/></div>}
      {monthAxis()}
    </div></div>
    <div className="cost-history"><div className="margin-history-title"><strong>AI cost</strong><span>Monthly actual cost · independent USD scale</span></div><div className="history-chart-scroll"><div className={`cost-history-chart${chartOverflowClass}`} style={chartSizing} onMouseLeave={()=>setCostActive(null)}><svg viewBox={`0 0 ${width} ${costHeight}`} role="img" aria-label="Monthly AI cost shown on an independent USD scale"><g className="history-grid"><line x1={left} y1={costTop} x2={width-right} y2={costTop}/><line x1={left} y1={costTop+costPlotHeight} x2={width-right} y2={costTop+costPlotHeight}/></g><g className="history-y-labels"><text x={left-10} y={costTop+4}>{money(maxCost)}</text><text x={left-10} y={costTop+costPlotHeight+4}>{money(0)}</text></g>{rows.map((row,index)=><rect className="history-cost-column" key={row.periodStart} x={x(index)-columnWidth/2} y={costY(row.aiCost)} width={columnWidth} height={Math.max(row.aiCost===0?1:3,costTop+costPlotHeight-costY(row.aiCost))} rx="3"/>)}</svg><div className="cost-hit-grid" style={{left:`${left/width*100}%`,right:`${right/width*100}%`}}>{rows.map((row,index)=><button key={row.periodStart} type="button" aria-label={`${historyMonthLabel(row.periodStart)} AI cost ${money(row.aiCost)}`} onMouseEnter={()=>setCostActive(index)} onFocus={()=>setCostActive(index)} onBlur={()=>setCostActive(null)}/>)}</div>{costSelected&&<div className="history-tooltip cost-tooltip" role="tooltip" style={{left:`${Math.max(12,Math.min(88,x(costActive!)/width*100))}%`}}><strong>{historyMonthLabel(costSelected.periodStart)}</strong><dl><div><dt>Revenue</dt><dd>{money(costSelected.revenue)}</dd></div><div><dt>AI cost</dt><dd>{money(costSelected.aiCost)}</dd></div><div><dt>Gross profit</dt><dd>{money(costSelected.grossProfit)}</dd></div><div><dt>Gross margin</dt><dd>{pct(costSelected.grossMargin)}</dd></div></dl><Status value={costSelected.status}/></div>}{monthAxis()}</div></div></div>
    <div className="margin-history"><div className="margin-history-title"><strong>Gross margin</strong><span>Monthly percentage</span></div><div className="history-chart-scroll"><div className={`margin-chart${chartOverflowClass}`} style={chartSizing} onMouseLeave={()=>setMarginActive(null)}><svg viewBox={`0 0 ${width} 108`} role="img" aria-label={`Monthly gross margin for the last ${months} months`}><g className="history-grid"><line x1={left} y1={marginTop} x2={width-right} y2={marginTop}/><line x1={left} y1={marginTop+marginPlotHeight/2} x2={width-right} y2={marginTop+marginPlotHeight/2}/><line x1={left} y1={marginTop+marginPlotHeight} x2={width-right} y2={marginTop+marginPlotHeight}/></g><g className="history-y-labels"><text x={left-10} y={marginTop+4}>{marginMax.toFixed(0)}%</text><text x={left-10} y={marginTop+marginPlotHeight+4}>{marginMin.toFixed(0)}%</text></g>{marginSegments.map((points,index)=><path className="margin-line" d={linePath(points)} key={index}/>)}{rows.map((row,index)=>row.grossMargin===null?null:<circle className="margin-point" key={row.periodStart} cx={x(index)} cy={marginY(row.grossMargin)} r="2.6"/>)}</svg><div className="margin-hit-grid" style={{left:`${left/width*100}%`,right:`${right/width*100}%`}}>{rows.map((row,index)=><button key={row.periodStart} type="button" aria-label={`${historyMonthLabel(row.periodStart)} gross margin ${pct(row.grossMargin)}`} onMouseEnter={()=>setMarginActive(index)} onFocus={()=>setMarginActive(index)} onBlur={()=>setMarginActive(null)}/>)}</div>{marginSelected&&<div className="margin-tooltip" role="tooltip" style={{left:`${Math.max(12,Math.min(88,x(marginActive!)/width*100))}%`}}><strong>{historyMonthLabel(marginSelected.periodStart)}</strong><span>{pct(marginSelected.grossMargin)}</span></div>}{monthAxis()}</div></div></div>
    <div className="table-wrap history-table"><table><thead><tr><th>Month</th><th className="number-col">Revenue</th><th className="number-col">AI Cost</th><th className="number-col">Gross Profit</th><th className="number-col">Gross Margin</th><th>Status</th></tr></thead><tbody>{[...rows].reverse().map(row=><tr key={row.periodStart}><td><strong>{historyMonthLabel(row.periodStart)}</strong></td><td className="number-col">{money(row.revenue)}</td><td className="number-col">{money(row.aiCost)}</td><td className={`number-col ${row.grossProfit<0?'negative':''}`}>{money(row.grossProfit)}</td><td className={`number-col ${row.grossMargin===null?'na-value':''}`}>{pct(row.grossMargin)}</td><td><Status value={row.status}/></td></tr>)}</tbody></table></div>
  </section>;
}

const profitabilityRanges=[{value:'7d',label:'Last 7 days'},{value:'30d',label:'Last 30 days'},{value:'current_month',label:'Current month'},{value:'previous_month',label:'Previous month'},{value:'custom',label:'Custom range'}] as const;
const overviewSortOptions=[{value:'highest_ai_cost',label:'Highest AI cost'},{value:'lowest_gross_margin',label:'Lowest gross margin'},{value:'highest_revenue',label:'Highest revenue'},{value:'highest_gross_profit',label:'Highest gross profit'}] as const;
const customerStatusOptions=[{value:'all',label:'All statuses'},{value:'healthy',label:'Healthy',tone:'healthy'},{value:'warning',label:'Warning',tone:'warning'},{value:'critical',label:'Critical',tone:'critical'},{value:'deleted',label:'Deleted',tone:'deleted'}] as const;
const customerSourceOptions=[{value:'all',label:'All sources'},{value:'stripe',label:'Stripe'},{value:'manual',label:'Manual'}] as const;
const customerSortOptions=[{value:'highest_ai_cost',label:'Highest AI cost'},{value:'lowest_margin',label:'Lowest margin'},{value:'highest_revenue',label:'Highest revenue'},{value:'name',label:'Name'}] as const;
type ProfitabilityRange=typeof profitabilityRanges[number]['value'];
type OverviewSort=typeof overviewSortOptions[number]['value'];
type OverviewStatus='all'|'healthy'|'warning'|'critical';
const rangeValue=(value:string|null):ProfitabilityRange=>profitabilityRanges.some(option=>option.value===value)?value as ProfitabilityRange:'current_month';
const overviewSortValue=(value:string|null):OverviewSort=>overviewSortOptions.some(option=>option.value===value)?value as OverviewSort:'lowest_gross_margin';
const overviewStatusValue=(value:string|null):OverviewStatus=>['all','healthy','warning','critical'].includes(value??'')?value as OverviewStatus:'all';
const overviewPageValue=(value:string|null)=>{const parsed=Number(value);return Number.isInteger(parsed)&&parsed>0?parsed:1;};
const effectiveRange=(range:ProfitabilityRange,start:string,end:string):ProfitabilityRange=>range==='custom'&&(!start||!end)?'current_month':range;
const rangeLabel=(range:string)=>({current_month:'Current calendar month',previous_month:'Previous calendar month','7d':'Last 7 days','30d':'Last 30 days',custom:'Custom period'}[range]??'Selected period');
function DateRangeControl({range,start,end,onRange,onStart,onEnd,className=''}:{range:ProfitabilityRange;start:string;end:string;onRange:(value:ProfitabilityRange)=>void;onStart:(value:string)=>void;onEnd:(value:string)=>void;className?:string}){return <section className={`analytics-controls ${className}`}><label><span>Date range</span><CustomSelect value={range} options={profitabilityRanges} onChange={onRange} ariaLabel="Date range"/></label>{range==='custom'&&<><label>Start<input type="date" value={start} onInput={event=>onStart(event.currentTarget.value)}/></label><label>End<input type="date" value={end} min={start} onInput={event=>onEnd(event.currentTarget.value)}/></label></>}</section>}

function OrganizationForecastCard({forecast}:{forecast:{data?:OrganizationForecastSummary;error:string;loading:boolean}}){
  const heading=<div className="organization-forecast-head"><div><div className="organization-forecast-title"><h2 id="organization-forecast-title">Month-end forecast</h2><span>Estimate · Current month</span></div><p>Projected from recent AI spend velocity.</p></div></div>;
  if(forecast.loading)return <section className="organization-forecast" aria-labelledby="organization-forecast-title">{heading}<p className="organization-forecast-state">Loading current-month forecast…</p></section>;
  if(forecast.error)return <section className="organization-forecast" aria-labelledby="organization-forecast-title">{heading}<div className="organization-forecast-state error">Forecast is temporarily unavailable.</div></section>;
  if(!forecast.data)return null;
  const data=forecast.data;
  const risk=data.highestForecastRisk;
  const exhaustionDate=risk?.budgetExhaustionDate?new Date(risk.budgetExhaustionDate):null;
  const exhausted=exhaustionDate!==null&&exhaustionDate.getTime()<=new Date(data.asOf).getTime();
  const riskCopy=exhausted?'Already exhausted':exhaustionDate?`May exhaust budget by ${exhaustionDate.toLocaleDateString(undefined,{month:'short',day:'numeric',timeZone:'UTC'})}`:'Forecast budget risk';
  return <section className="organization-forecast" aria-labelledby="organization-forecast-title">{heading}<div className="organization-forecast-body">{data.forecastStatus==='available'?<div className="organization-forecast-metrics"><div><span>Projected AI cost</span><strong>{money(data.projectedMonthEndAiCost!)}</strong><small>{money(data.currentMonthAiCost)} incurred this month</small></div><div><span>Projected gross margin</span><strong>{pct(data.projectedGrossMargin)}</strong><small>Estimated month end</small></div><div><span>Customers projected to exhaust</span><strong>{data.customersProjectedToExhaustBudgetThisMonth}</strong><small>Before month end</small></div></div>:<div className="organization-forecast-insufficient"><strong>Not enough current-month usage history for an organization forecast yet.</strong><span>Customer-level budget signals remain available below.</span></div>}<div className="organization-forecast-risk"><div className="forecast-risk-counts"><span><strong className={data.customersAlreadyBudgetExhausted>0?'critical':''}>{data.customersAlreadyBudgetExhausted}</strong> already exhausted</span><span><strong>{data.customersProjectedToExhaustBudgetThisMonth}</strong> projected this month</span><span><strong>{data.customersInsufficientData}</strong> lack enough history</span></div>{risk&&<Link aria-label={`Open ${risk.customerName} current-month profitability forecast`} to={`/customers/${risk.customerId}?range=current_month`}><span>Highest forecast risk</span><strong>{risk.customerName}</strong><small>{riskCopy}</small><i aria-hidden="true">→</i></Link>}</div></div></section>;
}

function CustomerCostDrivers({customerId,range,start,end,onRange,onStart,onEnd}:{customerId:string;range:ProfitabilityRange;start:string;end:string;onRange:(value:ProfitabilityRange)=>void;onStart:(value:string)=>void;onEnd:(value:string)=>void}){
  const resolvedRange=effectiveRange(range,start,end);const params=new URLSearchParams({range:resolvedRange});
  if(range==='custom'&&start&&end){params.set('startDate',start);params.set('endDate',end);}
  const drivers=useLoad<CustomerCostDriversResponse>(`/api/v1/analytics/profitability/customers/${customerId}/cost-drivers?${params.toString()}`);
  const header=<div className="cost-drivers-head"><div><h2>Cost drivers</h2><p>What's driving this customer's AI spend in the selected period.</p></div><DateRangeControl className="cost-drivers-range" range={range} start={start} end={end} onRange={onRange} onStart={onStart} onEnd={onEnd}/></div>;
  if(drivers.loading)return <section className="panel customer-cost-drivers">{header}<p className="cost-drivers-state">Loading cost drivers…</p></section>;
  if(drivers.error)return <section className="panel customer-cost-drivers">{header}<div className="error cost-drivers-error">{drivers.error}</div></section>;
  if(!drivers.data)return null;
  const change=(item:CustomerCostDriver)=>{if(item.direction==='flat')return '— No change';const arrow=item.direction==='up'?'↑':'↓';const amount=money(Math.abs(item.absoluteChange));if(item.percentChange===null&&item.previousPeriodAiCost===0)return `${arrow} ${amount} from $0`;return `${arrow} ${amount} (${item.percentChange!==null&&item.percentChange>0?'+':''}${item.percentChange?.toFixed(0)??'0'}%)`;};
  const list=(title:string,items:CustomerCostDriver[])=><article className="cost-driver-card"><h3>{title}</h3>{items.length?<div className="customer-driver-list">{items.slice(0,5).map(item=><div className="customer-driver-row" key={item.name}><div className="customer-driver-main"><strong title={item.name}>{item.name}</strong><span>{money(item.aiCost)} · {item.shareOfCustomerAiCost.toFixed(1)}% of AI cost</span></div><div className="customer-driver-share" aria-hidden="true"><i style={{width:`${Math.max(0,Math.min(100,item.shareOfCustomerAiCost))}%`}}/></div><div className="customer-driver-meta"><span className={`driver-change ${item.direction}`}>{change(item)}</span><small>{item.usageEventCount.toLocaleString()} usage event{item.usageEventCount===1?'':'s'}</small></div></div>)}</div>:<p className="cost-driver-empty">No AI cost drivers in this period.</p>}</article>;
  return <section className="panel customer-cost-drivers">{header}{drivers.data.totalAiCost===0?<p className="cost-drivers-state">No AI cost drivers in this period.</p>:<div className="customer-cost-driver-grid">{list('Top features',drivers.data.features)}{list('Top models',drivers.data.models)}</div>}</section>;
}

function Dashboard(){
  const [urlParams,setUrlParams]=useSearchParams();
  const range=rangeValue(urlParams.get('range'));
  const sort=overviewSortValue(urlParams.get('sort'));
  const customerFilter=overviewStatusValue(urlParams.get('status'));
  const page=overviewPageValue(urlParams.get('page'));const pageSize=20;
  const [costView,setCostView]=useState<'features'|'customers'|'models'|'providers'>('features');
  const start=urlParams.get('startDate')??'';
  const end=urlParams.get('endDate')??'';
  const updateOverviewParams=(changes:Record<string,string|null>,resetPage=true)=>{const next=new URLSearchParams(urlParams);Object.entries(changes).forEach(([key,value])=>value===null?next.delete(key):next.set(key,value));if(resetPage)next.set('page','1');setUrlParams(next);};
  const setRange=(value:ProfitabilityRange)=>updateOverviewParams({range:value,...(value==='custom'?{}:{startDate:null,endDate:null})});
  const setStart=(value:string)=>updateOverviewParams({startDate:value});
  const setEnd=(value:string)=>updateOverviewParams({endDate:value});
  const setSort=(value:OverviewSort)=>updateOverviewParams({sort:value});
  const setCustomerFilter=(value:OverviewStatus)=>updateOverviewParams({status:value});
  const drillToPeriodStatus=(value:'critical'|'warning')=>{setCustomerFilter(value);window.requestAnimationFrame(()=>document.getElementById('customer-profitability')?.scrollIntoView({behavior:'smooth',block:'start'}));};
  const setPage=(value:number)=>updateOverviewParams({page:String(Math.max(1,value))},false);
  const resolvedRange=effectiveRange(range,start,end);
  const params=new URLSearchParams({range:resolvedRange,sort,status:customerFilter,page:String(page),pageSize:String(pageSize)});
  if(range==='custom'&&start&&end){params.set('startDate',start);params.set('endDate',end);}
  const analytics=useLoad<Analytics>(`/api/v1/analytics/profitability?${params.toString()}`);
  const forecast=useLoad<OrganizationForecastSummary>('/api/v1/analytics/profitability/forecast-summary');
  const returnedPage=analytics.data&&!Array.isArray(analytics.data.customers)?analytics.data.customers:null;
  const lastAvailablePage=returnedPage?Math.max(1,Math.ceil(returnedPage.total/returnedPage.pageSize)):null;
  useEffect(()=>{if(lastAvailablePage!==null&&page>lastAvailablePage){const next=new URLSearchParams(urlParams);next.set('page',String(lastAvailablePage));setUrlParams(next,{replace:true});}},[lastAvailablePage,page,setUrlParams,urlParams]);
  if(analytics.error)return <div className="error">{analytics.error}</div>;
  if(analytics.loading||!analytics.data)return <p>Loading analytics…</p>;
  const data=analytics.data;
  const trendByDate=new Map(data.trend.map(point=>[point.date,point.cost]));
  const dailyTrend:{date:string;cost:number}[]=[];
  const trendEnd=new Date(data.period.endExclusive);
  for(let day=new Date(data.period.start);day<trendEnd;day=new Date(day.getTime()+86_400_000)){const date=day.toISOString().slice(0,10);dailyTrend.push({date,cost:trendByDate.get(date)??0});}
  const maxTrend=Math.max(0,...dailyTrend.map(point=>point.cost));
  const trendLabelInterval=Math.max(1,Math.ceil(dailyTrend.length/6));
  const marginTone=data.totals.grossMargin===null?'margin':data.totals.grossMargin<0?'risk':'margin';
  const periodParams=new URLSearchParams({range:data.period.range});
  if(data.period.range==='custom'&&start&&end){periodParams.set('startDate',start);periodParams.set('endDate',end);}
  const periodQuery=periodParams.toString();
  const overviewPeriodLabel=rangeLabel(data.period.range);
  const overviewPeriodDates=`${new Date(data.period.start).toLocaleDateString(undefined,{timeZone:'UTC'})}–${new Date(new Date(data.period.endExclusive).getTime()-1).toLocaleDateString(undefined,{timeZone:'UTC'})}`;
  const customerPage=Array.isArray(data.customers)?{items:data.customers,total:data.customers.length,page:1,pageSize}:data.customers;
  const criticalCount=data.currentHealth.critical;
  const warningCount=data.currentHealth.warning;
  const highestRisk=data.currentHealth.highestRisk;
  const pageStart=customerPage.total?(customerPage.page-1)*customerPage.pageSize+1:0;
  const pageEnd=Math.min(customerPage.page*customerPage.pageSize,customerPage.total);
  const costViews={features:{title:'Cost by feature',rows:data.breakdowns.features,empty:'No feature AI cost in this period.'},customers:{title:'Cost by customer',rows:data.breakdowns.customers.filter(row=>row.cost>0),empty:'No customer AI cost in this period.'},models:{title:'Cost by model',rows:data.breakdowns.models,empty:'No model AI cost in this period.'},providers:{title:'Cost by provider',rows:data.breakdowns.providers,empty:'No provider AI cost in this period.'}};
  const activeCostView=costViews[costView];
  return (
    <div className="overview-page"><PageHead eyebrow="" title="Profitability analytics" subtitle="See how recurring revenue converts into gross profit after AI costs." action={<div className="overview-header-actions"><DateRangeControl className="header-range-control" range={range} start={start} end={end} onRange={setRange} onStart={setStart} onEnd={setEnd}/></div>}/>
    <div className="selected-period-scope"><span>Selected-period analytics</span><strong>{overviewPeriodLabel}</strong><small>{overviewPeriodDates}</small></div>
    <section className="metrics analytics-metrics kpi-flow"><AnalyticsMetric label="Revenue" value={money(data.totals.revenue)} helper={<Term definition="Monthly recurring revenue active at the end of the selected period. It is not prorated revenue.">Period-end MRR</Term>}/><AnalyticsMetric tone="cost" label="AI cost" value={money(data.totals.aiCost)} helper="Usage cost in this period"/><AnalyticsMetric tone={data.totals.grossProfit<0?'risk':'profit'} label="Gross profit" value={money(data.totals.grossProfit)} helper="Revenue minus AI cost"/><AnalyticsMetric tone={marginTone} label="Gross margin" value={pct(data.totals.grossMargin)} helper={data.totals.grossMargin===null?'Not available without revenue':'Profit as a share of revenue'}/></section>
    <div className="overview-insight-row"><section className="trend-panel"><div className="panel-head"><div><h2>AI cost trend</h2><p>Selected-period daily AI spend · {overviewPeriodDates}</p></div><div className="trend-summary"><small>Period total</small><strong>{money(data.totals.aiCost)}</strong></div></div><div className="trend-chart" role="img" aria-label="Daily AI cost bar chart">{dailyTrend.map((point,index)=><div className={`trend-bar ${point.cost===0?'zero':''}`} key={point.date} aria-label={`${point.date}: ${money(point.cost)}`}><strong>{point.cost>0?money(point.cost):'—'}</strong><span style={{height:point.cost>0&&maxTrend?`${Math.max(5,(point.cost/maxTrend)*100)}%`:'2px'}}/><small>{index%trendLabelInterval===0||index===dailyTrend.length-1?new Date(`${point.date}T00:00:00Z`).toLocaleDateString(undefined,{month:'short',day:'numeric'}):' '}</small></div>)}</div></section><section className="attention-panel live-health" aria-labelledby="attention-title"><div className="attention-head"><div><span className="live-scope">Live · Latest state</span><h2 id="attention-title">Current health</h2></div><p>Canonical customer risk now, independent of the selected range.</p></div><div className="attention-counts"><button type="button" className="critical" aria-label={`Show ${criticalCount} Critical customers by selected-period status`} onClick={()=>drillToPeriodStatus('critical')}><strong>{criticalCount}</strong><span>Critical</span><small>View period status</small></button><button type="button" className="warning" aria-label={`Show ${warningCount} Warning customers by selected-period status`} onClick={()=>drillToPeriodStatus('warning')}><strong>{warningCount}</strong><span>Warning</span><small>View period status</small></button></div>{highestRisk?<Link aria-label={`Open current highest-risk customer ${highestRisk.name}`} className="highest-risk" to={`/customers/${highestRisk.customerId}?${periodQuery}`}><span>Highest risk</span><strong>{highestRisk.name}</strong><small>{pct(highestRisk.grossMargin)} margin · {money(highestRisk.aiCost)} AI cost{highestRisk.budgetUsedPercent!==null?` · ${pct(highestRisk.budgetUsedPercent)} budget used`:''}</small><i aria-hidden="true">→</i></Link>:<div className="attention-clear"><strong>All customers are healthy</strong><span>No customers currently need attention.</span></div>}</section></div>
    <OrganizationForecastCard forecast={forecast}/>
    <section className="profitability-changes" aria-labelledby="changes-title"><div><h2 id="changes-title">What changed?</h2><p>Broad profitability movement in the selected period vs the previous comparable period.</p></div>{data.insights.length?<ul>{data.insights.map((insight,index)=><li className={insight.tone} key={`${insight.text}-${index}`}>{insight.customerId?<Link aria-label={`${insight.text}. Open customer detail.`} to={`/customers/${insight.customerId}?${periodQuery}`}>{insight.text}<span aria-hidden="true">→</span></Link>:<span>{insight.text}</span>}</li>)}</ul>:<p className="no-changes">No significant profitability changes in this period.</p>}</section>
    {data.anomalies.length>0&&<section className="cost-anomalies" aria-labelledby="anomalies-title"><div><h2 id="anomalies-title">Cost anomalies</h2><p>Specific customer, feature, or model spend increases versus the previous comparable period.</p></div><ul>{data.anomalies.map(anomaly=>{const text=`${anomaly.name} AI cost ${anomaly.percentageIncrease===null?'increased from $0':`increased ${anomaly.percentageIncrease.toFixed(0)}%`} (+${money(anomaly.absoluteIncrease)}) vs the previous period.`;return <li className={anomaly.severity} key={`${anomaly.dimension}-${anomaly.name}`}>{anomaly.customerId?<Link aria-label={`${text} Open customer detail.`} to={`/customers/${anomaly.customerId}?${periodQuery}`}>{text}<span aria-hidden="true">→</span></Link>:<span>{text}</span>}<small>{anomaly.dimension}</small></li>})}</ul></section>}
    <section id="customer-profitability" className="panel customer-profitability"><div className="panel-head"><div><h2>Customer profitability</h2><p><Term definition="Monthly recurring revenue active at the end of the selected period. It is not prorated revenue.">Period-end MRR</Term>, AI cost, and status for the selected period.</p></div><div className="profitability-actions"><div className="filter-tabs" role="group" aria-label="Filter customers by selected-period guardrail state">{(['all','healthy','warning','critical'] as const).map(value=><button key={value} type="button" className={customerFilter===value?'active':''} aria-pressed={customerFilter===value} onClick={()=>setCustomerFilter(value)}>{value[0].toUpperCase()+value.slice(1)}</button>)}</div><label className="sort-control"><span>Sort by</span><CustomSelect value={sort} options={overviewSortOptions} onChange={setSort} ariaLabel="Sort customer profitability"/></label></div></div><CustomerTable rows={customerPage.items} periodQuery={periodQuery}/><div className="table-pagination"><span>{pageStart}–{pageEnd} of {customerPage.total}</span><div><button className="ghost dark" type="button" disabled={customerPage.page<=1} onClick={()=>setPage(page-1)}>Previous</button><button className="ghost dark" type="button" disabled={pageEnd>=customerPage.total} onClick={()=>setPage(page+1)}>Next</button></div></div></section>
    <section className="cost-intelligence"><div className="panel-head"><div><h2>Cost intelligence</h2><p>Understand what is driving AI cost in this period.</p></div><div className="cost-tabs" role="tablist" aria-label="Cost breakdown">{(['features','customers','models','providers'] as const).map(value=><button key={value} type="button" role="tab" aria-selected={costView===value} className={costView===value?'active':''} onClick={()=>setCostView(value)}>{value[0].toUpperCase()+value.slice(1)}</button>)}</div></div><div className="cost-intelligence-body"><div role="tabpanel" className="cost-tab-panel"><Breakdown title={activeCostView.title} rows={activeCostView.rows} emptyText={activeCostView.empty}/></div><section className="cost-driver-summary" aria-labelledby="drivers-title"><div><h3 id="drivers-title">Cost drivers</h3></div><div className="top-driver-insights"><TopDriverInsight label="Top customer" item={data.topCostDrivers.customers[0]}/><TopDriverInsight label="Top feature" item={data.topCostDrivers.features[0]}/><TopDriverInsight label="Top model" item={data.topCostDrivers.models[0]}/></div></section></div></section>
  </div>);
}

function Breakdown({title,rows,emptyText='No usage in this period.'}:{title:string;rows:{name:string;cost:number;requests?:number}[];emptyText?:string}){const max=Math.max(0,...rows.map(row=>row.cost));const total=rows.reduce((sum,row)=>sum+row.cost,0);return <section className="panel breakdown"><div className="panel-head"><div><h2>{title}</h2></div><strong className="breakdown-total">{money(total)}</strong></div>{rows.length?<div className="breakdown-list">{rows.map(row=><div key={row.name}><div><span>{row.name}</span><strong>{money(row.cost)}</strong></div><i style={{width:`${max?(row.cost/max)*100:0}%`}}/>{row.requests!==undefined&&<small>{row.requests.toLocaleString()} request{row.requests===1?'':'s'} · {total?((row.cost/total)*100).toFixed(1):'0.0'}% of cost</small>}</div>)}</div>:<p className="empty">{emptyText}</p>}</section>}
function TopDriverInsight({label,item}:{label:string;item?:{name:string;cost:number}}){return <div className="top-driver-insight"><span>{label}</span>{item?<><strong>{item.name}</strong><small>{money(item.cost)}</small></>:<em>No cost in this period</em>}</div>}

function Customers(){
  const [urlParams,setUrlParams]=useSearchParams();
  const [range,setRange]=useState<ProfitabilityRange>(rangeValue(urlParams.get('range'))); const [start,setStart]=useState(urlParams.get('startDate')??''); const [end,setEnd]=useState(urlParams.get('endDate')??'');
  const resolvedRange=effectiveRange(range,start,end); const periodParams=new URLSearchParams({range:resolvedRange});
  if(range==='custom'&&start&&end){periodParams.set('startDate',start);periodParams.set('endDate',end);}
  const periodQuery=periodParams.toString();
  const customers=useLoad<Customer[]>('/api/v1/customers'); const [open,setOpen]=useState(false); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  const profitability=useLoad<Analytics>(`/api/v1/analytics/profitability?${periodQuery}&sort=lowest_gross_margin`);
  const profitabilityByCustomer=useMemo(()=>{const rows=profitability.data?(Array.isArray(profitability.data.customers)?profitability.data.customers:profitability.data.customers.items):[];return new Map(rows.map(row=>[row.customerId,row]));},[profitability.data]);
  const [search,setSearch]=useState(''); const [statusFilter,setStatusFilter]=useState('all'); const [sourceFilter,setSourceFilter]=useState('all'); const [sort,setSort]=useState('highest_ai_cost');
  const visibleCustomers=useMemo(()=>{
    const query=search.trim().toLocaleLowerCase();
    return [...(customers.data??[])].filter(customer=>{
      const row=profitabilityByCustomer.get(customer.id);
      const matchesSearch=!query||customer.name.toLocaleLowerCase().includes(query)||customer.externalCustomerId.toLocaleLowerCase().includes(query);
      const matchesStatus=statusFilter==='all'||(row&&customerRiskState(row)===statusFilter);
      const matchesSource=sourceFilter==='all'||customer.revenueSource===sourceFilter;
      return matchesSearch&&matchesStatus&&matchesSource;
    }).sort((a,b)=>{
      const aRow=profitabilityByCustomer.get(a.id); const bRow=profitabilityByCustomer.get(b.id);
      if(sort==='lowest_margin') return (aRow?.grossMargin??Number.POSITIVE_INFINITY)-(bRow?.grossMargin??Number.POSITIVE_INFINITY);
      if(sort==='highest_revenue') return (bRow?.revenue??b.monthlyRevenue)-(aRow?.revenue??a.monthlyRevenue);
      if(sort==='name') return a.name.localeCompare(b.name,undefined,{sensitivity:'base'});
      return (bRow?.aiCost??0)-(aRow?.aiCost??0);
    });
  },[customers.data,profitabilityByCustomer,search,statusFilter,sourceFilter,sort]);
  useEffect(()=>{const next=new URLSearchParams({range});if(range==='custom'&&start&&end){next.set('startDate',start);next.set('endDate',end);}setUrlParams(next,{replace:true});},[range,start,end,setUrlParams]);
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setError('');const f=new FormData(e.currentTarget);try{await request('/api/v1/customers',{method:'POST',body:JSON.stringify({externalCustomerId:f.get('externalId'),name:f.get('name'),email:f.get('email')||null,monthlyRevenue:Number(f.get('revenue')),currency:'USD'})});setOpen(false);await Promise.all([customers.reload(),profitability.reload()]);}catch(x){setError((x as Error).message);}finally{setBusy(false);}}
  if(customers.error)return <div className="error">{customers.error}</div>;
  const selectedPeriodLabel=profitability.data?rangeLabel(profitability.data.period.range):rangeLabel(resolvedRange);
  return <><PageHead eyebrow={selectedPeriodLabel} title="Customers" subtitle="Map recurring revenue to AI spend for each account." action={<div className="customer-header-actions"><DateRangeControl className="header-range-control" range={range} start={start} end={end} onRange={setRange} onStart={setStart} onEnd={setEnd}/><button onClick={()=>setOpen(true)}>New customer</button></div>}/><div className="customer-toolbar"><label className="customer-search"><span className="sr-only">Search customers</span><input type="search" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search name or identifier…"/></label><label><span>Status</span><CustomSelect value={statusFilter} options={customerStatusOptions} onChange={setStatusFilter} ariaLabel="Customer status"/></label><label><span>Source</span><CustomSelect value={sourceFilter} options={customerSourceOptions} onChange={setSourceFilter} ariaLabel="Revenue source"/></label><label><span>Sort</span><CustomSelect value={sort} options={customerSortOptions} onChange={setSort} ariaLabel="Sort customers"/></label></div><section className="panel cards customer-grid">{customers.loading?<p className="empty">Loading customers…</p>:customers.data?.length?(visibleCustomers.length?visibleCustomers.map(c=>{const row=profitabilityByCustomer.get(c.id);const riskState=row?customerRiskState(row):null;return <Link className={`customer-card profitability-card ${riskState?`risk-${riskState}`:''}`} to={`/customers/${c.id}?${periodQuery}`} key={c.id}><div className="customer-card-head"><div><h3>{c.name}</h3><span className="customer-external-id">{c.externalCustomerId}</span></div>{riskState?<BudgetIndicator value={riskState}/>:<span className="status-pending">{profitability.loading?'Loading…':'Unavailable'}</span>}</div><dl className="customer-card-metrics"><div><dt>Revenue / MRR</dt><dd className={(row?.revenue??c.monthlyRevenue)===0?'muted-value':''}>{money(row?.revenue??c.monthlyRevenue,c.currency)}</dd></div><div><dt>AI cost</dt><dd className={!row?'muted-value':''}>{row?money(row.aiCost):'—'}</dd></div><div><dt>Gross margin</dt><dd className={!row||row.grossMargin===null?'muted-value':row.grossMargin<0?'negative':''}>{row?pct(row.grossMargin):'—'}</dd></div></dl><div className="customer-card-foot"><span className={`revenue-source ${c.revenueSource}`}>{c.revenueSource==='stripe'?'Stripe':'Manual'}</span>{c.revenueStale&&<em>Revenue may be stale</em>}<span className="card-arrow" aria-hidden="true">→</span></div></Link>}):<p className="empty">No customers match these filters.</p>):<p className="empty">No customers yet. Add one to begin measuring margin.</p>}</section>{open&&<div className="modal"><form className="dialog" onSubmit={submit}><div><h2>Add customer</h2><p>Add manual MRR; Stripe sync creates Stripe-backed customers automatically.</p></div><label>Name<input name="name" required maxLength={200} placeholder="ACME"/></label><label>External ID<input name="externalId" required maxLength={200} placeholder="acme_001"/></label><label>Billing email<input name="email" type="email" maxLength={320} placeholder="billing@acme.example"/></label><label>Manual MRR<input name="revenue" type="number" step="0.01" min="0" required placeholder="100.00"/></label>{error&&<div className="error">{error}</div>}<div className="actions"><button className="ghost" type="button" disabled={busy} onClick={()=>setOpen(false)}>Cancel</button><button disabled={busy}>{busy?'Adding…':'Add customer'}</button></div></form></div>}</>;
}

function DetailMetric({label,value,tone='neutral',muted=false}:{label:string;value:string;tone?:'neutral'|'healthy'|'warning'|'critical';muted?:boolean}){return <article className={`detail-metric ${tone} ${muted?'muted':''}`}><span>{label}</span><strong>{value}</strong></article>}

function CustomerDetail(){
  const {id}=useParams(); const [searchParams,setSearchParams]=useSearchParams();
  const [range,setRange]=useState<ProfitabilityRange>(rangeValue(searchParams.get('range')));
  const [start,setStart]=useState(searchParams.get('startDate')??'');
  const [end,setEnd]=useState(searchParams.get('endDate')??'');
  const resolvedRange=effectiveRange(range,start,end);
  const periodParams=new URLSearchParams({range:resolvedRange});
  if(range==='custom'&&start&&end){periodParams.set('startDate',start);periodParams.set('endDate',end);}
  const periodQuery=periodParams.toString();
  const margin=useLoad<Margin>(`/api/v1/customers/${id}/margin`);
  const periodProfitability=useLoad<CustomerPeriodProfitability>(`/api/v1/analytics/profitability/customers/${id}?${periodQuery}`);
  const [formError,setFormError]=useState(''); const [busy,setBusy]=useState(false);const [guardrailMessage,setGuardrailMessage]=useState('');
  useEffect(()=>{const next=new URLSearchParams({range});if(range==='custom'&&start&&end){next.set('startDate',start);next.set('endDate',end);}setSearchParams(next,{replace:true});},[range,start,end,setSearchParams]);
  async function usage(e:FormEvent<HTMLFormElement>){
    e.preventDefault(); if(busy)return; const form=e.currentTarget; const f=new FormData(form); setBusy(true); setFormError('');
    try {
      await request('/api/v1/usage',{method:'POST',body:JSON.stringify({customerId:id,provider:f.get('provider'),model:f.get('model'),feature:f.get('feature'),inputTokens:Number(f.get('inputTokens')),outputTokens:Number(f.get('outputTokens')),cost:Number(f.get('cost')),externalRequestId:f.get('requestId'),occurredAt:new Date().toISOString()})});
      form.reset(); (form.elements.namedItem('requestId') as HTMLInputElement).value=crypto.randomUUID(); await Promise.all([margin.reload(),periodProfitability.reload()]);
    } catch(x) { setFormError((x as Error).message); } finally { setBusy(false); }
  }
  async function guardrails(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;const f=new FormData(e.currentTarget);const optional=(name:string)=>f.get(name)===''?null:Number(f.get(name));setBusy(true);setGuardrailMessage('');try{await request(`/api/v1/customers/${id}/guardrails`,{method:'PUT',body:JSON.stringify({targetGrossMargin:optional('target'),warningThreshold:optional('warning'),criticalThreshold:optional('critical')})});setGuardrailMessage('Customer guardrails updated.');await Promise.all([margin.reload(),periodProfitability.reload()]);}catch(x){setGuardrailMessage((x as Error).message);}finally{setBusy(false);}}
  if(margin.error||periodProfitability.error)return <div className="error">{margin.error||periodProfitability.error}</div>; if(margin.loading||periodProfitability.loading||!margin.data||!periodProfitability.data)return <p>Loading customer profitability…</p>; const profile=margin.data; const data={...profile,...periodProfitability.data}; const showDevelopmentTools=import.meta.env.DEV;
  const periodLabel=rangeLabel(data.period.range);
  const periodDates=`${new Date(data.period.start).toLocaleDateString(undefined,{timeZone:'UTC'})}–${new Date(new Date(data.period.endExclusive).getTime()-1).toLocaleDateString(undefined,{timeZone:'UTC'})}`;
  const maxFeatureCost=Math.max(0,...data.features.map(feature=>feature.cost));
  return <div className="customer-detail-page">
    <PageHead eyebrow="" title={data.name} subtitle="Customer profitability, budget health, and recent AI usage." action={<div className="customer-detail-header-actions"><DateRangeControl className="detail-header-range" range={range} start={start} end={end} onRange={setRange} onStart={setStart} onEnd={setEnd}/><div className="customer-status-summary"><div><small>Margin</small><Status value={data.status}/></div><div><small>Budget</small><BudgetIndicator value={data.budgetState}/></div></div></div>}/>
    {data.revenueStale&&<div className="notice">Stripe revenue may be stale. Reconnect and synchronize Stripe to verify it.</div>}{data.stripeCustomerStatus==='deleted'&&<div className="notice lifecycle">This Stripe customer was deleted. Historical customer, subscription, usage, and margin data remain preserved.</div>}
    <div className="detail-period-context"><div><span>Profitability period</span><strong>{periodLabel}</strong><small>{periodDates}</small></div><Link to={`/dashboard?${periodQuery}`}>Back to Overview</Link></div>
    <section className="detail-current-state" aria-labelledby="current-state-title"><div className="detail-layer-heading"><div><h2 id="current-state-title">Current state</h2><p>Actual profitability and budget position for {periodLabel.toLowerCase()}.</p></div></div><div className="primary-profitability-metrics"><DetailMetric label="Revenue / MRR" value={money(data.revenue)} muted={data.revenue===0}/><DetailMetric label="AI cost" value={money(data.aiCost)} tone={data.budgetState==='critical'?'critical':data.budgetState==='warning'?'warning':'neutral'} muted={data.aiCost===0}/><DetailMetric label="Gross profit" value={money(data.grossProfit)} tone={data.grossProfit<0?'critical':data.grossProfit>0?'healthy':'neutral'}/><DetailMetric label="Gross margin" value={pct(data.grossMargin)} tone={data.grossMargin===null?'neutral':data.grossMargin<0||data.status==='critical'?'critical':data.status==='warning'||data.status==='atRisk'?'warning':'healthy'} muted={data.grossMargin===null}/></div>
    <div className="secondary-budget-metrics" aria-label="Budget details"><DetailMetric label="Target margin" value={pct(data.targetGrossMargin)}/><DetailMetric label="Allowed AI budget" value={money(data.allowedAiBudget)} muted={data.revenue===0}/><DetailMetric label="Remaining budget" value={money(data.remainingAiBudget)} muted={data.revenue===0}/><DetailMetric label="Budget used" value={pct(data.budgetUsedPercent)} muted={data.budgetUsedPercent===null}/></div></section>
    <MonthEndForecast customerId={id!}/>
    <CustomerCostDrivers customerId={id!} range={range} start={start} end={end} onRange={setRange} onStart={setStart} onEnd={setEnd}/>
    <ProfitabilityHistory customerId={id!}/>
    <div className="detail-operational-heading"><h2>Operational details</h2><p>Detailed activity and billing context for this customer.</p></div>
    <section className="panel feature-cost-panel"><div className="panel-head"><div><h2>Cost by feature</h2><p>Detailed breakdown · {periodLabel}</p></div></div>{data.features.length?<div className="feature-cost-list">{data.features.map(feature=><div className="feature-cost-row" key={feature.feature}><div><span>{feature.feature}</span><strong>{money(feature.cost)}</strong></div><i><span style={{width:`${maxFeatureCost?(feature.cost/maxFeatureCost)*100:0}%`}}/></i></div>)}</div>:<p className="empty">No usage in this period.</p>}</section>
    <section className="panel recent-usage-panel"><div className="panel-head"><div><h2>Recent usage</h2><p>Most recent 25 cost events · {periodLabel}</p></div></div><div className="table-wrap"><table><thead><tr><th>Occurred</th><th>Provider and model</th><th>Feature</th><th>Tokens</th><th className="usage-cost-column">Cost</th></tr></thead><tbody>{data.recentUsage?.length?data.recentUsage.map(u=><tr key={u.id}><td className="usage-time"><strong>{new Date(u.occurredAt).toLocaleDateString()}</strong><small>{new Date(u.occurredAt).toLocaleTimeString()}</small></td><td className="usage-model"><strong>{u.model}</strong><small>{u.provider}</small></td><td><span className="feature-label">{u.feature}</span></td><td className="usage-tokens">{(u.inputTokens+u.outputTokens).toLocaleString()}</td><td className="usage-cost-column"><strong>{money(u.cost)}</strong></td></tr>):<tr><td colSpan={5} className="empty">No usage events in this period.</td></tr>}</tbody></table></div></section>
    {data.revenueSource==='stripe'?<section className="panel billing stripe-billing"><div className="panel-head"><div><h2>Billing</h2><p>Source: <strong>Stripe</strong>{data.stripeCustomerId&&<> · Customer {data.stripeCustomerId}</>} · <strong>{data.stripeCustomerStatus[0].toUpperCase()+data.stripeCustomerStatus.slice(1)}</strong></p></div></div>{data.subscriptions?.length?<div className="table-wrap"><table><thead><tr><th>Subscription</th><th>Status</th><th>MRR</th><th>Period end</th><th>Notes</th></tr></thead><tbody>{data.subscriptions.map(s=><tr key={s.id}><td>{s.name}</td><td>{s.status}{s.cancelAtPeriodEnd?' · cancels at period end':''}</td><td>{money(s.monthlyRecurringRevenue,s.currency)}</td><td>{s.currentPeriodEnd?new Date(s.currentPeriodEnd).toLocaleDateString():'—'}</td><td>{s.warning||'—'}</td></tr>)}</tbody></table></div>:<p className="empty">No Stripe subscriptions were returned by the latest sync.</p>}</section>:<section className="manual-billing-row"><h2>Billing</h2><p><strong>Source: Manual</strong><span>Manually maintained MRR</span></p></section>}
    <section className="panel guardrail-settings customer-guardrails"><div className="guardrail-heading"><div><h2>Customer guardrails</h2><p>Edits apply to the current policy. Leave a field blank to inherit the organization policy.</p></div><span className="effective-thresholds">Current warning {pct(profile.warningThreshold)} · Critical {pct(profile.criticalThreshold)}</span></div><form onSubmit={guardrails}><label>Target margin<input name="target" type="number" min="0.01" max="99.99" step="0.01" defaultValue={profile.targetGrossMarginOverride??''} placeholder="Inherit"/></label><label>Warning used %<input name="warning" type="number" min="0" max="99.99" step="0.01" defaultValue={profile.warningThresholdOverride??''} placeholder="Inherit"/></label><label>Critical used %<input name="critical" type="number" min="0.01" max="100" step="0.01" defaultValue={profile.criticalThresholdOverride??''} placeholder="Inherit"/></label><button disabled={busy}>Save overrides</button></form>{guardrailMessage&&<span className="message">{guardrailMessage}</span>}</section>
    {showDevelopmentTools&&<section className="panel development-usage-tool"><div className="panel-head"><div><h2>Usage ingestion test tool</h2><p>Submit a calculated usage event during local development.</p></div></div><form className="compact" onSubmit={usage}><label>Provider<input name="provider" defaultValue="openai" required maxLength={100}/></label><label>Model<input name="model" defaultValue="gpt-5" required maxLength={200}/></label><label>Feature<input name="feature" defaultValue="chat" required maxLength={200}/></label><label>Cost (USD)<input name="cost" type="number" step="0.000001" min="0" required/></label><label>Input tokens<input name="inputTokens" type="number" min="0" step="1" defaultValue="0" required/></label><label>Output tokens<input name="outputTokens" type="number" min="0" step="1" defaultValue="0" required/></label><label className="wide">External request ID<input name="requestId" defaultValue={crypto.randomUUID()} required maxLength={300}/></label>{formError&&<div className="error wide">{formError}</div>}<button className="wide" disabled={busy}>{busy?'Recording…':'Record usage'}</button></form></section>}
  </div>;
}

const sdkExample=`import { Margintra } from '@margintra/node';

const margintra = new Margintra({
  apiKey: process.env.MARGINTRA_API_KEY!,
});

await margintra.usage.recordOpenAI({
  externalRequestId: response.id,
  customerId: 'cus_123',
  model: response.model,
  feature: 'support-chat',
  usage: { inputTokens, outputTokens },
  occurredAt: new Date().toISOString(),
});`;

const curlExample=`curl --request POST "\${MARGINTRA_API_URL}/api/v1/ingest/usage" \\
  --header "Content-Type: application/json" \\
  --header "X-Margintra-Key: \${MARGINTRA_API_KEY}" \\
  --data-raw '{
    "externalRequestId": "req_123",
    "customerId": "cus_123",
    "provider": "openai",
    "model": "gpt-5",
    "feature": "support-chat",
    "usage": {
      "inputTokens": 1200,
      "outputTokens": 300
    },
    "occurredAt": "2026-09-02T12:00:00.000Z"
  }'`;

function SyntaxCode({code,language}:{code:string;language:'node'|'curl'}){
  void language;
  const pattern=/(\/\/.*$|process\.env\.[A-Z0-9_]+|\$\{[A-Z0-9_]+\}|\$[A-Z][A-Z0-9_]*|--[a-z-]+|'(?:\\.|[^'])*'|"(?:\\.|[^"])*"|\b(?:import|from|const|new|await|curl|POST)\b|\b(?:true|false|null)\b|\b[A-Za-z_$][\w$]*(?=\s*[(:])|\b\d+\b|[{}\[\](),.;:])/gm;
  const output:React.ReactNode[]=[];let cursor=0;let key=0;
  for(const match of code.matchAll(pattern)){const token=match[0];const index=match.index;if(index>cursor)output.push(<span key={key++}>{code.slice(cursor,index)}</span>);const following=code.slice(index+token.length);const className=token.startsWith('//')?'comment':/^(?:process\.env\.|\$)/.test(token)?'constant':/^['"]/.test(token)?(/^\s*:/.test(following)?'property':'string'):/^\d+$|^(?:true|false|null)$/.test(token)?'number':/^[{}\[\](),.;:]$/.test(token)?'punctuation':/^\s*\(/.test(following)?'function':/^\s*:/.test(following)?'property':'keyword';output.push(<span className={`code-token ${className}`} key={key++}>{token}</span>);cursor=index+token.length;}if(cursor<code.length)output.push(<span key={key}>{code.slice(cursor)}</span>);return <code>{output}</code>;
}

function CopyButton({value,className='',label='Copy'}:{value:string;className?:string;label?:string}){
  const [state,setState]=useState<'idle'|'copied'|'failed'>('idle');const timer=useRef<number|undefined>(undefined);
  useEffect(()=>{setState('idle');window.clearTimeout(timer.current);return()=>window.clearTimeout(timer.current);},[value]);
  async function copy(){window.clearTimeout(timer.current);try{await navigator.clipboard.writeText(value);setState('copied');}catch{setState('failed');}timer.current=window.setTimeout(()=>setState('idle'),2000);}
  return <button className={`copy-feedback ${state} ${className}`.trim()} type="button" onClick={()=>void copy()}>{state==='copied'?'Copied ✓':state==='failed'?'Copy failed':label}</button>;
}

const docsSections=[
  ['getting-started','Getting started'],['stripe-setup','Stripe setup'],
  ['webhook-setup','Webhook setup'],['usage-ingestion','Usage ingestion'],
  ['api-keys','API keys'],['troubleshooting','Troubleshooting'],
] as const;
const docsScrollOffset=()=>window.innerWidth<=760?118:92;
const stripeWebhookEvents=['customer.created','customer.updated','customer.deleted','customer.subscription.created','customer.subscription.updated','customer.subscription.deleted','customer.subscription.paused','customer.subscription.resumed','price.updated','product.updated'];
function DocsCode({code,language}:{code:string;language:'node'|'curl'}){return <div className="code-example docs-code"><div className="code-example-head"><span>{language==='node'?'Node.js':'cURL'}</span><CopyButton className="code-copy" value={code}/></div><pre><SyntaxCode code={code} language={language}/></pre></div>}

function DocsFigure({src,alt,caption}:{src:string;alt:string;caption:string}){
  return <figure className="docs-figure"><img src={src} alt={alt}/><figcaption>{caption}</figcaption></figure>;
}

function DocsPage(){
  const location=useLocation();
  const navigate=useNavigate();
  const smoothHash=useRef(false);
  const navigationTarget=useRef<{id:string;until:number}|null>(null);
  const hashSection=decodeURIComponent(location.hash.slice(1));
  const [activeSection,setActiveSection]=useState(
    docsSections.some(([id])=>id===hashSection)?hashSection:docsSections[0][0],
  );
  useEffect(()=>{
    if(!location.hash)return;
    const id=decodeURIComponent(location.hash.slice(1));
    if(!docsSections.some(([sectionId])=>sectionId===id))return;
    navigationTarget.current={id,until:Date.now()+3000};
    setActiveSection(id);
    let second=0;
    const first=window.requestAnimationFrame(()=>{
      second=window.requestAnimationFrame(()=>{
        document.getElementById(id)?.scrollIntoView({behavior:smoothHash.current?'smooth':'auto',block:'start'});
        smoothHash.current=false;
      });
    });
    return()=>{window.cancelAnimationFrame(first);window.cancelAnimationFrame(second);};
  },[location.hash]);
  useEffect(()=>{
    const sections=docsSections.map(([id])=>document.getElementById(id)).filter((section):section is HTMLElement=>!!section);
    let frame=0;
    const resolve=()=>{
      frame=0;
      const pending=navigationTarget.current;
      if(pending){
        const target=document.getElementById(pending.id);
        const reached=target&&(Math.abs(target.getBoundingClientRect().top-docsScrollOffset())<=8||
          (pending.id===sections.at(-1)?.id&&window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-2));
        if(!reached&&Date.now()<pending.until){
          setActiveSection(pending.id);
          return;
        }
      }
      navigationTarget.current=null;
      const anchor=Math.max(docsScrollOffset()+4,window.innerHeight*.25);
      const atBottom=window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-2;
      const active=atBottom?sections.at(-1):[...sections].reverse().find(section=>section.getBoundingClientRect().top<=anchor)??sections[0];
      if(!active)return;
      setActiveSection(active.id);
      if(window.location.hash!==`#${active.id}`)window.history.replaceState(window.history.state,'',`${window.location.pathname}${window.location.search}#${active.id}`);
    };
    const schedule=()=>{if(!frame)frame=window.requestAnimationFrame(resolve);};
    resolve();
    window.addEventListener('scroll',schedule,{passive:true});
    window.addEventListener('resize',schedule);
    return()=>{window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);window.cancelAnimationFrame(frame);};
  },[]);
  const navigateToSection=(event:React.MouseEvent<HTMLAnchorElement>,id:string)=>{
    event.preventDefault();
    smoothHash.current=true;
    navigationTarget.current={id,until:Date.now()+3000};
    setActiveSection(id);
    if(location.hash===`#${id}`){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
    void navigate({pathname:location.pathname,search:location.search,hash:`#${id}`});
  };
  return <div className="docs-shell">
    <header className="docs-topbar"><Link className="docs-brand" to="/dashboard"><span>M</span><strong>Margintra</strong><small>Developer docs</small></Link><Link className="docs-app-link" to="/dashboard">Open Margintra →</Link></header>
    <div className="docs-layout">
      <aside className="docs-nav" aria-label="Documentation"><strong>Setup guide</strong><nav>{docsSections.map(([id,label])=><a key={id} href={`#${id}`} className={activeSection===id?'active':undefined} aria-current={activeSection===id?'location':undefined} onClick={event=>navigateToSection(event,id)}>{label}</a>)}</nav></aside>
      <main className="docs-content">
        <section className="docs-intro" id="getting-started"><span className="eyebrow">Developer setup</span><h1>Connect revenue and usage data</h1><p>Configure Stripe as your revenue source, then send customer-level AI usage from your backend to Margintra.</p><ol className="docs-steps"><li><span>1</span><div><strong>Connect Stripe</strong><small>Create a restricted Read-only key.</small></div></li><li><span>2</span><div><strong>Configure webhooks</strong><small>Keep revenue changes synchronized.</small></div></li><li><span>3</span><div><strong>Send usage</strong><small>Attribute AI cost to native customer IDs.</small></div></li></ol></section>
        <section id="stripe-setup"><h2>Stripe setup</h2><p>Create a restricted key that can read only the Stripe resources Margintra needs. You do not need a full-access secret key.</p><ol className="docs-numbered"><li><div><strong>Open API keys</strong><p>Sign in to Stripe Dashboard. Open <strong>Developers → API keys</strong>, then choose <strong>Create restricted key</strong>. If your account uses Workbench, API keys are available from its developer tools.</p></div></li><li><div><strong>Name the key</strong><p>Use a recognizable name such as <strong>Margintra production</strong> or <strong>Margintra test</strong>, and make sure you are in the intended Stripe mode.</p></div></li><li><div><strong>Grant the required Read access</strong><p>Set <strong>Accounts, Customers, Subscriptions, Prices, and Products</strong> to <strong>Read</strong>.</p></div></li><li><div><strong>Leave every other permission restricted</strong><p>Everything else can remain <strong>None</strong>. Margintra requires no Write permissions.</p></div></li><li><div><strong>Connect Margintra</strong><p>Create the key, copy the resulting <code>rk_test_...</code> or <code>rk_live_...</code> value, and paste it into <strong>Margintra → Integrations → Stripe</strong>. Margintra encrypts it at rest and does not display it again.</p></div></li></ol><div className="docs-callout"><strong>Required Read permissions</strong><ul><li>Accounts</li><li>Customers</li><li>Subscriptions</li><li>Prices</li><li>Products</li></ul><p>Everything else: <strong>None</strong>. No Write permissions are required.</p></div><DocsFigure src="/docs/stripe-restricted-permissions.svg" alt="Sanitized Stripe restricted-key permission screen with Accounts, Customers, Subscriptions, Prices, and Products set to Read" caption="In Stripe, set these five resources to Read and leave every other resource at None."/><DocsFigure src="/docs/margintra-stripe-connect.svg" alt="Sanitized Margintra Stripe integration form with the restricted key field highlighted" caption="In Margintra, open Integrations → Stripe and enter the newly created restricted key."/></section>
        <section id="webhook-setup"><h2>Webhook setup</h2><p>Create a Stripe event destination so subscription and customer changes reach your Margintra deployment.</p><ol className="docs-numbered"><li><div><strong>Open Stripe Dashboard</strong><p>Sign in and select the same mode—test or live—as the restricted key connected to Margintra.</p></div></li><li><div><strong>Open Webhooks</strong><p>Go to <strong>Workbench → Webhooks</strong>. On accounts using the older navigation, open <strong>Developers → Webhooks</strong>.</p></div></li><li><div><strong>Create an event destination</strong><p>Choose <strong>Create destination</strong> or <strong>Add destination</strong>, select events from your account, and choose <strong>Webhook</strong> as the destination type.</p><DocsFigure src="/docs/stripe-webhook-destination.svg" alt="Sanitized Stripe Workbench Webhooks screen showing the Create destination action" caption="Create a webhook event destination in Stripe Workbench."/></div></li><li><div><strong>Paste the Margintra endpoint</strong><p>Copy the exact URL shown in <strong>Margintra → Integrations → Stripe → Webhook setup</strong> and paste it into Stripe’s Endpoint URL field.</p><div className="docs-endpoint"><span>Expected route shape</span><code>https://&lt;your-margintra-domain&gt;/api/v1/webhooks/stripe/&lt;connection-identifier&gt;</code></div><DocsFigure src="/docs/margintra-webhook-setup.svg" alt="Sanitized Margintra Webhook setup panel showing the endpoint copy control and webhook signing secret field" caption="Copy the endpoint URL from Margintra, then return here with the matching Stripe signing secret."/></div></li><li><div><strong>Select Margintra events</strong><p>Add each event listed below. Do not substitute a broad event list.</p><div className="docs-event-list">{stripeWebhookEvents.map(event=><code key={event}>{event}</code>)}</div><DocsFigure src="/docs/stripe-event-selection.svg" alt="Sanitized Stripe event selection screen with Margintra customer, subscription, price, and product events selected" caption="Search for and select the exact event types listed in this guide."/></div></li><li><div><strong>Create the destination</strong><p>Review the selected events and endpoint URL, then create or save the destination.</p></div></li><li><div><strong>Reveal the signing secret</strong><p>Open the new destination’s details and reveal or copy its <code>whsec_...</code> signing secret. Use the secret from this exact endpoint.</p><DocsFigure src="/docs/stripe-signing-secret.svg" alt="Sanitized Stripe destination details screen showing the signing secret reveal control" caption="Reveal and copy the signing secret from the destination details."/></div></li><li><div><strong>Save the secret in Margintra</strong><p>Return to <strong>Margintra → Integrations → Stripe → Webhook setup</strong>, paste the <code>whsec_...</code> value, and choose <strong>Update secret</strong>.</p></div></li></ol></section>
        <section id="usage-ingestion"><h2>Usage ingestion</h2><p>Create a Margintra ingestion API key, store it on your backend, and send usage to <code>/api/v1/ingest/usage</code>. The <code>customerId</code> must be the billing provider's native ID—for Stripe, use <code>cus_...</code>. The internal <code>stripe:</code> namespace is not part of the public contract.</p><DocsFigure src="/docs/margintra-usage-setup.svg" alt="Sanitized Margintra onboarding integration example with Node.js and cURL tabs" caption="Onboarding provides matching Node.js SDK and direct cURL examples for backend integration."/><DocsCode code={sdkExample} language="node"/><DocsCode code={curlExample} language="curl"/><p>Use a stable, unique <code>externalRequestId</code> for retries. Equivalent retries do not create another event; a materially different payload with the same ID returns a conflict.</p></section>
        <section id="api-keys"><h2>API keys</h2><p>Create keys under <strong>Margintra → Integrations → Usage API keys</strong>. The plaintext secret is shown once and stored only as a hash.</p><DocsFigure src="/docs/margintra-api-keys.svg" alt="Sanitized Margintra Usage API keys table showing Create, Rotate key, and Revoke actions" caption="Create an ingestion key, rotate active keys when needed, and revoke keys that should no longer authenticate."/><ul><li>Keep keys in server-side environment variables.</li><li>Never place a key in browser or frontend code.</li><li>Revoke a key that is no longer used.</li><li>If a key is lost, rotate it and update your backend immediately. Secrets cannot be recovered.</li></ul></section>
        <section id="troubleshooting"><h2>Troubleshooting</h2><dl className="docs-troubleshooting"><div><dt>Missing Stripe permission</dt><dd>Set the named resource to Read. Margintra checks Accounts, Customers, Subscriptions, Prices, and Products.</dd></div><div><dt>Invalid Stripe key</dt><dd>Use the complete active <code>rk_test_...</code> or <code>rk_live_...</code> restricted key.</dd></div><div><dt>Invalid webhook secret</dt><dd>Use the <code>whsec_...</code> secret from the exact endpoint configured for this Margintra connection.</dd></div><div><dt>CUSTOMER_NOT_FOUND</dt><dd>Synchronize Stripe and send a native <code>cus_...</code> customer ID belonging to the same organization.</dd></div><div><dt>INVALID_API_KEY or API_KEY_REVOKED</dt><dd>Send an active Margintra ingestion key in the <code>X-Margintra-Key</code> header.</dd></div><div><dt>DUPLICATE_REQUEST_CONFLICT</dt><dd>The request ID was already accepted with materially different usage facts. Use a new ID for a genuinely different event.</dd></div></dl></section>
      </main>
    </div>
  </div>;
}

const onboardingSteps=['Connect Stripe','Create usage API key','Add SDK to backend','Receive first usage event','Finish setup'];
function OnboardingProgress({current}:{current:number}){return <nav className="onboarding-progress" aria-label="Setup progress"><ol>{onboardingSteps.map((label,index)=>{const number=index+1;const complete=number<current;const active=number===current;return <li key={label} className={complete?'complete':active?'active':''} aria-current={active?'step':undefined}><span>{complete?'✓':number}</span><small>{label}</small></li>})}</ol></nav>}

function Onboarding(){
  const nav=useNavigate();const status=useLoad<OnboardingState>('/api/v1/onboarding');const [welcome,setWelcome]=useState(false);const [sdkSeen,setSdkSeen]=useState(false);const [readyToFinish,setReadyToFinish]=useState(false);const [exampleTab,setExampleTab]=useState<'node'|'curl'>('node');const [newSecret,setNewSecret]=useState('');const [busy,setBusy]=useState('');const [error,setError]=useState('');const [usageCheckMessage,setUsageCheckMessage]=useState('');const [stripeErrors,setStripeErrors]=useState<{secretKey?:string;webhookSecret?:string}>({});
  const confirmedSteps=useRef({stripeConnected:false,ingestionKeyCreated:false});
  if(status.data?.stripeConnected)confirmedSteps.current.stripeConnected=true;
  if(status.data?.ingestionKeyCreated)confirmedSteps.current.ingestionKeyCreated=true;
  const data=status.data?{...status.data,stripeConnected:status.data.stripeConnected||confirmedSteps.current.stripeConnected,ingestionKeyCreated:status.data.ingestionKeyCreated||confirmedSteps.current.ingestionKeyCreated}:undefined;
  const reloadOnboarding=status.reload;
  const requiresOnboarding=data?.requiresOnboarding;
  const shouldPollUsage=!!data?.ingestionKeyCreated&&!data.firstUsageReceived;
  useEffect(()=>{if(requiresOnboarding===false)void nav('/dashboard',{replace:true});},[requiresOnboarding,nav]);
  useEffect(()=>{if(!shouldPollUsage)return;const timer=window.setInterval(()=>void reloadOnboarding(),5000);return()=>window.clearInterval(timer);},[shouldPollUsage,reloadOnboarding]);
  async function start(){setBusy('start');setError('');try{await request('/api/v1/onboarding/start',{method:'POST'});setWelcome(true);await status.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function connect(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const secretKey=String(f.get('secretKey')??'').trim();const webhookSecret=String(f.get('webhookSecret')??'').trim();const fields:{secretKey?:string;webhookSecret?:string}={};if(!secretKey)fields.secretKey='Enter your Stripe restricted API key.';else if(!/^rk_(test|live)_[A-Za-z0-9]+$/.test(secretKey))fields.secretKey='Enter a valid Stripe restricted API key.';if(webhookSecret&&!/^whsec_[A-Za-z0-9]+$/.test(webhookSecret))fields.webhookSecret='Enter a valid Stripe webhook signing secret.';setStripeErrors(fields);setError('');if(Object.keys(fields).length)return;setBusy('stripe');try{await request('/api/v1/integrations/stripe/connect',{method:'POST',body:JSON.stringify({secretKey,webhookSecret:webhookSecret||null})});form.reset();await status.reload();}catch(x){const detail=(x as Error).message;const lower=detail.toLowerCase();const permission=detail.match(/^This Stripe key is missing a required permission: (Account|Customers|Subscriptions|Prices|Products) Read\.$/);if(permission)setStripeErrors({secretKey:`${permission[1]} Read permission is missing.`});else if(lower.includes('missing required read permissions'))setStripeErrors({secretKey:'This Stripe key is missing required Read permissions. Check Customers, Subscriptions, Prices, and Products.'});else if(lower.includes('could not authenticate'))setStripeErrors({secretKey:'Stripe could not authenticate this restricted key.'});else if(lower.includes('temporarily unavailable'))setError('Stripe is temporarily unavailable. Please try again.');else setError('We couldn’t connect Stripe right now. Please try again.');}finally{setBusy('');}}
  async function createKey(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const f=new FormData(form);setBusy('key');setError('');try{const key=await request<UsageApiKey>('/api/v1/integrations/usage-api-keys',{method:'POST',body:JSON.stringify({name:f.get('name')})});setNewSecret(key.secret||'');form.reset();await status.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function syncStripe(){setBusy('sync');setError('');try{await request('/api/v1/integrations/stripe/sync',{method:'POST'});await status.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function checkUsage(){setBusy('check');setUsageCheckMessage('');const latest=await status.reload();if(!latest?.firstUsageReceived)setUsageCheckMessage('No usage received yet.');setBusy('');}
  async function finish(){setBusy('finish');setError('');try{await request('/api/v1/onboarding/complete',{method:'POST'});void nav('/dashboard',{replace:true});}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  if(status.error)return <div className="error">{status.error}</div>;if(!data)return <p>Loading onboarding…</p>;
  const missingStripePermission=stripeErrors.secretKey?.match(/^(Account|Customers|Subscriptions|Prices|Products) Read permission is missing\.$/)?.[1];
  const missingStripeResource=missingStripePermission==='Account'?'Accounts':missingStripePermission;
  if(!welcome&&!data.startedAt)return <section className="onboarding onboarding-welcome"><span className="eyebrow">Welcome to Margintra</span><h1>See the margin behind every customer</h1><p>A short guided setup will connect revenue and AI cost data. You can complete it in five steps.</p><OnboardingProgress current={1}/>{error&&<div className="error">{error}</div>}<button disabled={!!busy} onClick={()=>void start()}>{busy?'Starting…':'Start setup'}</button></section>;
  if(!data.stripeConnected)return <section className="onboarding"><OnboardingProgress current={1}/><div className="onboarding-heading"><span className="eyebrow">Step 1 of 5</span><h1>Connect Stripe</h1><p>Connect recurring revenue so Margintra can measure customer profitability.</p></div><form className="onboarding-form" onSubmit={connect} noValidate><div className="onboarding-field"><label>Stripe restricted key <small>Stored securely and never shown again</small><input name="secretKey" type="password" autoComplete="off" maxLength={512} placeholder="rk_test_…" aria-invalid={!!stripeErrors.secretKey} aria-describedby={stripeErrors.secretKey?'stripe-key-error':undefined}/>{stripeErrors.secretKey&&<span id="stripe-key-error" className="inline-error" role="alert">{stripeErrors.secretKey}</span>}{missingStripeResource&&<small className="permission-action">In Stripe restricted key settings, search for ‘{missingStripeResource}’ and set the {missingStripeResource} resource to Read.</small>}<span className="stripe-permissions-helper"><strong>Required Read permissions:</strong> Account, Customers, Subscriptions, Prices, Products. <small>Everything else can remain None. No Write permissions are required.</small></span></label><a className="setup-guide-link" href={`${DEVELOPER_GUIDE}#stripe-setup`} target="_blank" rel="noopener noreferrer">How to create this key ↗</a></div><div className="onboarding-field"><label>Webhook signing secret <small>Optional during initial setup</small><input name="webhookSecret" type="password" autoComplete="off" maxLength={512} placeholder="whsec_…" aria-invalid={!!stripeErrors.webhookSecret} aria-describedby={stripeErrors.webhookSecret?'stripe-webhook-error':undefined}/>{stripeErrors.webhookSecret&&<span id="stripe-webhook-error" className="inline-error" role="alert">{stripeErrors.webhookSecret}</span>}</label><a className="setup-guide-link" href={`${DEVELOPER_GUIDE}#webhook-setup`} target="_blank" rel="noopener noreferrer">Webhook setup guide ↗</a></div>{error&&<div className="error">{error}</div>}<button disabled={!!busy}>{busy?'Connecting…':'Connect Stripe'}</button></form></section>;
  if(!data.ingestionKeyCreated||newSecret)return <section className="onboarding"><OnboardingProgress current={2}/><div className="onboarding-heading"><span className="eyebrow">Step 2 of 5</span><h1>Create a usage API key</h1><p>This key lets your backend send AI usage totals to Margintra.</p></div><div className="onboarding-security"><strong>Server-side only</strong><span>Keep this key in your backend environment. Never place it in frontend or browser code.</span></div>{newSecret?<div className="secret-once"><strong>Copy this key now. You won't be able to view it again.</strong><input readOnly value={newSecret}/><div className="actions left"><CopyButton value={newSecret}/><button className="ghost dark" type="button" onClick={()=>setNewSecret('')}>I saved it securely</button></div></div>:<form className="onboarding-form" onSubmit={createKey}><label>Key name<input name="name" required maxLength={100} defaultValue="Production backend"/></label>{error&&<div className="error">{error}</div>}<button disabled={!!busy}>{busy?'Creating…':'Create API key'}</button></form>}</section>;
  if(!sdkSeen){const activeExample=exampleTab==='node'?sdkExample:curlExample;return <section className="onboarding wide-onboarding"><OnboardingProgress current={3}/><div className="onboarding-heading"><span className="eyebrow">Step 3 of 5</span><h1>Add the SDK to your backend</h1><p>Use the Node.js SDK or send the same usage data directly over HTTP.</p></div><div className="onboarding-security"><strong>Backend code only</strong><span>Never put the ingestion key or this integration in frontend browser code.</span></div><div className="code-example"><div className="code-example-head"><div className="code-tabs" role="tablist" aria-label="Integration example"><button type="button" role="tab" aria-selected={exampleTab==='node'} className={exampleTab==='node'?'active':''} onClick={()=>setExampleTab('node')}>Node.js</button><button type="button" role="tab" aria-selected={exampleTab==='curl'} className={exampleTab==='curl'?'active':''} onClick={()=>setExampleTab('curl')}>cURL</button></div><CopyButton className="code-copy" value={activeExample}/></div><pre><SyntaxCode code={activeExample} language={exampleTab}/></pre></div><button onClick={()=>setSdkSeen(true)}>I added the SDK</button></section>;}
  if(readyToFinish)return <section className="onboarding"><OnboardingProgress current={5}/><div className="onboarding-heading"><span className="eyebrow">Step 5 of 5</span><h1>Finish setup</h1><p>Margintra is ready. You can start reviewing customer profitability now and verify usage later if needed.</p></div>{error&&<div className="error">{error}</div>}<div className="actions left"><button disabled={!!busy} onClick={()=>void finish()}>{busy==='finish'?'Finishing…':'Finish setup'}</button></div></section>;
  return <section className="onboarding"><OnboardingProgress current={4}/><div className="onboarding-heading"><span className="eyebrow">Step 4 of 5</span><h1>{data.firstUsageReceived?'Your first usage event arrived':'Waiting for your first usage event'}</h1><p>{data.firstUsageReceived?'Margintra is receiving usage data and is ready to calculate customer profitability.':'Send one event from your backend. Margintra checks automatically every five seconds.'}</p></div><div className={`usage-receipt-state ${data.firstUsageReceived?'received':'waiting'}`}><span className="receipt-icon">{data.firstUsageReceived?'✓':'•••'}</span><div><strong>{data.firstUsageReceived?'Usage data received':'Listening for usage data'}</strong><small>{data.firstUsageReceived?`${data.usageEventCount} usage event${data.usageEventCount===1?'':'s'} received`:'Automatic check is active'}</small></div></div><div className="flow-status"><span className={data.customerCount?'done':''}>{data.customerCount?'✓':'○'} Customer available ({data.customerCount})</span><span className={data.firstUsageReceived?'done':''}>{data.firstUsageReceived?'✓':'○'} Usage received ({data.usageEventCount})</span></div>{!data.customerCount&&<p>Synchronize Stripe or <Link to="/customers">add a customer</Link> so the SDK can resolve its external customer ID.</p>}{data.customerCount>0&&data.usageEventCount===0&&<p>Send one usage event from your backend using the Margintra SDK or ingestion API.</p>}{!data.firstUsageReceived&&<p>You can finish setup now and verify usage later.</p>}{usageCheckMessage&&<p className="message" role="status">{usageCheckMessage}</p>}{error&&<div className="error">{error}</div>}<div className="actions left">{!data.customerCount&&<button className="ghost dark" disabled={!!busy} onClick={()=>void syncStripe()}>{busy==='sync'?'Synchronizing…':'Sync Stripe now'}</button>}<button className="ghost dark" disabled={!!busy} onClick={()=>void checkUsage()}>{busy==='check'?'Checking…':'Check for usage'}</button><button disabled={!!busy} onClick={()=>setReadyToFinish(true)}>Continue</button></div></section>;
}

function Integrations(){
  const stripe=useLoad<StripeConnection>('/api/v1/integrations/stripe'); const [busy,setBusy]=useState(''); const [message,setMessage]=useState(''); const [error,setError]=useState('');
  const usageKeys=useLoad<UsageApiKey[]>('/api/v1/integrations/usage-api-keys'); const [newSecret,setNewSecret]=useState(''); const [rotatedSecret,setRotatedSecret]=useState(false);
  async function connect(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;const form=e.currentTarget;const f=new FormData(form);setBusy('connect');setError('');setMessage('');try{await request('/api/v1/integrations/stripe/connect',{method:'POST',body:JSON.stringify({secretKey:f.get('secretKey'),webhookSecret:f.get('webhookSecret')||null})});form.reset();setMessage('Stripe connected. Run the initial synchronization to import MRR.');await stripe.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function updateWebhook(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;const form=e.currentTarget;const f=new FormData(form);setBusy('webhook');setError('');setMessage('');try{await request('/api/v1/integrations/stripe/webhook-secret',{method:'PUT',body:JSON.stringify({webhookSecret:f.get('webhookSecret')})});form.reset();setMessage('Webhook signing secret updated.');await stripe.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function sync(){if(busy)return;setBusy('sync');setError('');setMessage('');try{const result=await request<{customers:number;subscriptions:number;warnings:number}>('/api/v1/integrations/stripe/sync',{method:'POST'});setMessage(`Synchronized ${result.customers} customers and ${result.subscriptions} subscriptions${result.warnings?` with ${result.warnings} warning(s)`:''}.`);await stripe.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function disconnect(){if(busy)return;setBusy('disconnect');setError('');setMessage('');try{await request('/api/v1/integrations/stripe',{method:'DELETE'});setMessage('Stripe disconnected. Last synchronized MRR was preserved and marked stale.');await stripe.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function createUsageKey(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;const form=e.currentTarget;const f=new FormData(form);setBusy('usage-key');setError('');try{const key=await request<UsageApiKey>('/api/v1/integrations/usage-api-keys',{method:'POST',body:JSON.stringify({name:f.get('name')})});setRotatedSecret(false);setNewSecret(key.secret||'');form.reset();await usageKeys.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function revokeUsageKey(id:string){if(busy)return;setBusy(`revoke-${id}`);setError('');try{await request(`/api/v1/integrations/usage-api-keys/${id}`,{method:'DELETE'});await usageKeys.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  async function rotateUsageKey(id:string){if(busy||!window.confirm('Rotating this key will revoke the current key. Update your backend with the new key immediately.'))return;setBusy(`rotate-${id}`);setError('');try{const key=await request<UsageApiKey>(`/api/v1/integrations/usage-api-keys/${id}/rotate`,{method:'POST'});setRotatedSecret(true);setNewSecret(key.secret||'');await usageKeys.reload();}catch(x){setError((x as Error).message);}finally{setBusy('');}}
  if(stripe.error)return <div className="error">{stripe.error}</div>;if(stripe.loading||!stripe.data)return <p>Loading integrations…</p>;const data=stripe.data;
  return <><PageHead title="Integrations" subtitle="Connect revenue and securely ingest customer-level AI usage."/>
    <div className="integrations-layout">
      <section className="panel integration-card stripe-integration">
        <div className="integration-title"><div className="stripe-mark">S</div><div><span className="section-kicker">Revenue integration</span><h2>Stripe</h2><p>Synchronize customer recurring subscription revenue.</p><a className="setup-guide-link" href={`${DEVELOPER_GUIDE}#stripe-setup`} target="_blank" rel="noopener noreferrer">Setup guide ↗</a></div></div>
        {data.connected?<div className="connection-detail">
          <div className="connection-overview"><div><span className="connection connected"><i/>Connected</span><h3>Stripe is connected</h3><p>Revenue synchronization is available for this workspace.</p></div><div className="actions integration-actions"><button className="ghost dark sync-action" disabled={!!busy} onClick={sync}>{busy==='sync'?'Synchronizing…':'Sync now'}</button><button className="disconnect-action" disabled={!!busy} onClick={disconnect}>{busy==='disconnect'?'Disconnecting…':'Disconnect'}</button></div></div>
          <div className="stripe-metadata" aria-label="Stripe connection details"><div><span>Mode</span><strong><span className={`mode-badge ${data.liveMode?'live':'test'}`}>{data.liveMode?'Live':'Test'}</span></strong></div><div><span>Last successful sync</span><strong>{data.lastSuccessfulSyncAt?new Date(data.lastSuccessfulSyncAt).toLocaleString():'Not yet synchronized'}</strong></div><div><span>Webhook</span><strong><span className={`webhook-state ${data.webhookConfigured?'configured':''}`}>{data.webhookConfigured?'Configured':'Not configured'}</span></strong></div><div className="account-fact"><span>Account ID</span><strong>{data.accountId}</strong></div></div>
          {data.lastError&&<div className="error">{data.lastError}</div>}
          <details className="advanced-webhook"><summary><span><strong>Webhook setup</strong><small>Add the Margintra endpoint to Stripe and save the signing secret.</small></span></summary><div className="advanced-webhook-body"><section className="webhook-step"><div className="webhook-step-heading"><span>Step 1</span><h4>Add endpoint to Stripe</h4></div>{data.webhookPath&&<div className="webhook-endpoint"><label>Margintra webhook endpoint<input className="technical-input" readOnly value={`${location.origin}${data.webhookPath}`}/></label><CopyButton className="ghost dark webhook-copy" label="Copy URL" value={`${location.origin}${data.webhookPath}`}/></div>}<p>In Stripe Dashboard, go to Developers → Webhooks, add an endpoint, and paste this URL.</p></section><section className="webhook-step"><div className="webhook-step-heading"><span>Step 2</span><h4>Add signing secret</h4></div><form className="webhook-form" onSubmit={updateWebhook}><label>Webhook signing secret <small>After creating the Stripe webhook endpoint, copy its signing secret and paste it here.</small><input name="webhookSecret" type="password" autoComplete="off" required maxLength={512} placeholder="whsec_…"/></label><button disabled={!!busy}>{busy==='webhook'?'Updating…':'Update secret'}</button></form></section><a className="setup-guide-link" href={`${DEVELOPER_GUIDE}#webhook-setup`} target="_blank" rel="noopener noreferrer">Webhook setup guide ↗</a></div></details>
        </div>:<div className="disconnected-state"><div className="connection-overview"><div><span className="connection"><i/>Disconnected</span><h3>Connect Stripe revenue</h3><p>Use a restricted server-side credential to synchronize customers and subscriptions.</p></div></div><form className="connect-form" onSubmit={connect}><p>Prefer a restricted test key with only the required read permissions.</p><label>Stripe secret or restricted key<input name="secretKey" type="password" autoComplete="off" required maxLength={512} placeholder="sk_test_… or rk_test_…"/></label><label>Webhook signing secret <small>Optional until webhooks are configured</small><input name="webhookSecret" type="password" autoComplete="off" maxLength={512} placeholder="whsec_…"/></label><button disabled={!!busy}>{busy==='connect'?'Verifying…':'Connect Stripe'}</button></form></div>}
        {error&&<div className="error integration-message">{error}</div>}{message&&<div className="success integration-message">{message}</div>}
      </section>
      <section className="panel integration-card api-key-integration">
        <div className="integration-title"><div className="stripe-mark ai-mark">AI</div><div><span className="section-kicker">Usage ingestion</span><h2>Usage API keys</h2><p>Authenticate server-side SDK and HTTP telemetry ingestion.</p></div><span className="key-count">{usageKeys.data?.filter(key=>key.status==='active').length??0} active</span></div>
        <div className="notice api-key-notice">Keep ingestion keys on backend servers only. Send usage metadata, never prompts or completions.</div>
        {newSecret&&<div className="secret-once"><strong>{rotatedSecret?'Key rotated. Update your backend with this new key immediately.':'Copy this key now.'}</strong><span>This key will not be shown again.</span><input readOnly value={newSecret}/><div className="actions left"><CopyButton value={newSecret}/><button className="ghost dark" type="button" onClick={()=>setNewSecret('')}>I saved it</button></div></div>}
        <form className="connect-form key-create-form" onSubmit={createUsageKey}><label>Key name<input name="name" required maxLength={100} placeholder="Production backend"/></label><button disabled={!!busy}>{busy==='usage-key'?'Creating…':'Create usage API key'}</button></form>
        {usageKeys.error&&<div className="error integration-message">{usageKeys.error}</div>}{usageKeys.loading?<p className="integration-loading">Loading keys…</p>:<div className="table-wrap api-key-table"><table><thead><tr><th>Name</th><th>Status</th><th>Prefix</th><th>Created</th><th>Last used</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{usageKeys.data?.map(key=><tr key={key.id} className={key.status==='revoked'?'revoked-row':''}><td className="key-name">{key.name}</td><td><span className={`key-status ${key.status}`}>{key.status}</span></td><td><code>{key.keyPrefix}…</code></td><td className="secondary-cell">{new Date(key.createdAt).toLocaleDateString()}</td><td className="last-used-cell">{key.lastUsedAt?new Date(key.lastUsedAt).toLocaleString():'Never used'}</td><td>{key.status==='active'&&<div className="key-actions"><button className="ghost dark rotate-action" disabled={!!busy} onClick={()=>void rotateUsageKey(key.id)}>{busy===`rotate-${key.id}`?'Rotating…':'Rotate key'}</button><button className="revoke-action" disabled={!!busy} onClick={()=>void revokeUsageKey(key.id)}>{busy===`revoke-${key.id}`?'Revoking…':'Revoke'}</button></div>}</td></tr>)}{usageKeys.data?.length===0&&<tr><td colSpan={6} className="empty">No usage API keys yet.</td></tr>}</tbody></table></div>}
      </section>
    </div>
  </>;
}

function Settings(){
  const settings=useLoad<{targetGrossMargin:number;warningThreshold:number;criticalThreshold:number}>('/api/v1/settings/margin'); const [guardrailMessage,setGuardrailMessage]=useState(''); const [notificationMessage,setNotificationMessage]=useState(''); const [busy,setBusy]=useState(false);
  const notifications=useLoad<{emailEnabled:boolean;warningAlertsEnabled:boolean;criticalAlertsEnabled:boolean;recoveryAlertsEnabled:boolean;recipients:string[]}>('/api/v1/settings/notifications');
  const [guardrails,setGuardrails]=useState({target:'',warning:'',critical:''});
  const [emailEnabled,setEmailEnabled]=useState(false); const [warningEnabled,setWarningEnabled]=useState(true); const [criticalEnabled,setCriticalEnabled]=useState(true); const [recoveryEnabled,setRecoveryEnabled]=useState(true);
  const [recipients,setRecipients]=useState<string[]>([]); const [recipientInput,setRecipientInput]=useState(''); const [recipientError,setRecipientError]=useState('');
  useEffect(()=>{if(settings.data)setGuardrails({target:String(settings.data.targetGrossMargin),warning:String(settings.data.warningThreshold),critical:String(settings.data.criticalThreshold)});},[settings.data]);
  useEffect(()=>{if(notifications.data){setEmailEnabled(notifications.data.emailEnabled);setWarningEnabled(notifications.data.warningAlertsEnabled);setCriticalEnabled(notifications.data.criticalAlertsEnabled);setRecoveryEnabled(notifications.data.recoveryAlertsEnabled);setRecipients(notifications.data.recipients);}},[notifications.data]);
  const parseSetting=(value:string)=>value.trim()===''?NaN:Number(value);
  const target=parseSetting(guardrails.target); const warning=parseSetting(guardrails.warning); const critical=parseSetting(guardrails.critical);
  const allowedBudget=Number.isFinite(target)?100*(1-target/100):NaN;
  const example=(value:number)=>Number.isFinite(allowedBudget)&&Number.isFinite(value)?money(allowedBudget*(value/100)):'—';
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setGuardrailMessage('');try{await request('/api/v1/settings/margin',{method:'PUT',body:JSON.stringify({targetGrossMargin:target,warningThreshold:warning,criticalThreshold:critical})});setGuardrailMessage('Organization guardrails updated.');await settings.reload();}catch(x){setGuardrailMessage((x as Error).message);}finally{setBusy(false);}}
  function addRecipient(){const email=recipientInput.trim().toLowerCase();setRecipientError('');if(!email)return;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){setRecipientError('Enter a valid email address.');return;}if(recipients.includes(email)){setRecipientError('That recipient is already added.');return;}if(recipients.length>=10){setRecipientError('You can add up to 10 recipients.');return;}setRecipients(current=>[...current,email]);setRecipientInput('');}
  async function saveNotifications(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setNotificationMessage('');setRecipientError('');try{await request('/api/v1/settings/notifications',{method:'PUT',body:JSON.stringify({emailEnabled,warningAlertsEnabled:warningEnabled,criticalAlertsEnabled:criticalEnabled,recoveryAlertsEnabled:recoveryEnabled,recipients})});setNotificationMessage('Notification preferences updated.');await notifications.reload();}catch(x){setNotificationMessage((x as Error).message);}finally{setBusy(false);}}
  if(settings.error||notifications.error)return <div className="error">{settings.error||notifications.error}</div>;
  return <><PageHead eyebrow="" title="Margin policy" subtitle="Set non-blocking profitability guardrails and notification preferences."/>
    <div className="settings-layout">
      <section className="panel settings guardrail-policy"><div className="settings-section-head"><div><span className="section-kicker">Profitability policy</span><h2>AI budget guardrails</h2><p>Allowed AI budget is derived from revenue and target margin. Warning and critical thresholds are percentages of that budget used.</p></div></div>{settings.loading?<p>Loading settings…</p>:settings.data&&<><form onSubmit={submit} className="guardrail-form"><label>Target gross margin<div className="suffix"><input name="margin" type="number" required min="0.01" max="99.99" step="0.01" value={guardrails.target} onChange={e=>setGuardrails({...guardrails,target:e.target.value})}/><span>%</span></div></label><label>Warning at<div className="suffix"><input name="warning" type="number" required min="0" max="99.99" step="0.01" value={guardrails.warning} onChange={e=>setGuardrails({...guardrails,warning:e.target.value})}/><span>%</span></div></label><label>Critical at<div className="suffix"><input name="critical" type="number" required min="0.01" max="100" step="0.01" value={guardrails.critical} onChange={e=>setGuardrails({...guardrails,critical:e.target.value})}/><span>%</span></div></label><button disabled={busy}>{busy?'Saving…':'Save guardrails'}</button></form><div className="guardrail-example"><div><span className="example-label">Live example</span><strong>For $100 MRR</strong></div><dl><div><dt>Allowed AI budget</dt><dd>{Number.isFinite(allowedBudget)?money(allowedBudget):'—'}</dd></div><div><dt>Warning at</dt><dd>{example(warning)}</dd></div><div><dt>Critical at</dt><dd>{example(critical)}</dd></div></dl></div>{guardrailMessage&&<span className="message settings-message">{guardrailMessage}</span>}</>}</section>
      <section className="panel settings notification-settings"><div className="settings-section-head notification-head"><div><span className="section-kicker">Alert delivery</span><h2>Email notifications</h2><p>Send profitability and budget transitions by email. Delivery never blocks financial processing.</p></div><label className="toggle-row"><span>{emailEnabled?'On':'Off'}</span><input type="checkbox" role="switch" aria-label="Email notifications" checked={emailEnabled} onChange={e=>setEmailEnabled(e.target.checked)}/><i aria-hidden="true"/></label></div>{notifications.loading?<p>Loading notifications…</p>:notifications.data&&<form onSubmit={saveNotifications} className="notification-form"><fieldset disabled={!emailEnabled} className={!emailEnabled?'is-disabled':''}><legend>Notify me when</legend><div className="notification-events"><label className="event-option"><input type="checkbox" checked={warningEnabled} onChange={e=>setWarningEnabled(e.target.checked)}/><span><strong>Customer enters Warning</strong><small>AI budget usage crosses the warning threshold.</small></span></label><label className="event-option"><input type="checkbox" checked={criticalEnabled} onChange={e=>setCriticalEnabled(e.target.checked)}/><span><strong>Customer becomes Critical</strong><small>AI budget is exhausted or margin becomes critical.</small></span></label><label className="event-option"><input type="checkbox" checked={recoveryEnabled} onChange={e=>setRecoveryEnabled(e.target.checked)}/><span><strong>Customer recovers</strong><small>A previous warning or critical condition resolves.</small></span></label></div><div className="recipient-editor"><label htmlFor="recipient-email">Recipients</label><div className={`chip-input ${recipientError?'invalid':''}`}>{recipients.map(email=><span className="email-chip" key={email}>{email}<button type="button" aria-label={`Remove ${email}`} onClick={()=>setRecipients(current=>current.filter(item=>item!==email))}>×</button></span>)}<input id="recipient-email" type="email" value={recipientInput} disabled={!emailEnabled||recipients.length>=10} placeholder={recipients.length?'Add another email':'finance@example.com'} onChange={e=>{setRecipientInput(e.target.value);setRecipientError('');}} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addRecipient();}}}/></div><small>Type an email and press Enter. Up to 10 recipients.</small>{recipientError&&<span className="inline-error" role="alert">{recipientError}</span>}</div></fieldset><button disabled={busy}>{busy?'Saving…':'Save notifications'}</button></form>}{notificationMessage&&<span className="message settings-message">{notificationMessage}</span>}</section>
    </div></>;
}

function App(){return <Routes><Route path="/login" element={<Auth/>}/><Route path="/register" element={<Auth register/>}/><Route path="/docs" element={<DocsPage/>}/><Route element={<Guard/>}><Route path="/onboarding" element={<Onboarding/>}/><Route path="/dashboard" element={<Dashboard/>}/><Route path="/customers" element={<Customers/>}/><Route path="/customers/:id" element={<CustomerDetail/>}/><Route path="/integrations" element={<Integrations/>}/><Route path="/settings" element={<Settings/>}/></Route><Route path="*" element={<Navigate to="/dashboard"/>}/></Routes>}
const rootElement=document.getElementById('root');
if(!rootElement)throw new Error('Root element not found.');
createRoot(rootElement).render(<React.StrictMode><BrowserRouter><App/></BrowserRouter></React.StrictMode>);
